const activeNav = () => view==='community-heat'?'home':navItems[view]?view:['emergency-finder','aed-finder'].includes(view)?'nearby':view.startsWith('water-')?'water-events':view.startsWith('field-')?'field-manager':view==='emergency'?'guide':['random-drill','site-drill','drill-places','place-drills','linked-drill','coach','facility','plan','setup','training','whatif','fork-training'].includes(view)?'scenarios':'records';
