let siteDrillDraft={place:'',scenario:'',name:'',condition:'auto',notes:'',responders:'',details:{},detailsOpen:false};
function drillPlaceOptions(current,blank=false){
  let options=blank?'<option value="">장소 유형 선택</option>':'';
  for(const group of Object.values(DRILL_GROUPS)){
    const places=Object.fromEntries(group.places.map(id=>[id,DRILL_PLACES[id].name]));
    options+='<optgroup label="'+escapeHTML(group.name)+'">'+optionList(places,current)+'</optgroup>';
  }
  return options;
}
function responderCountField(value=''){
  return `<label class="field" for="drill-responders">지금 대응할 수 있는 인원 <small class="muted">필수</small><input id="drill-responders" type="number" name="responders" inputmode="numeric" min="1" max="10000" step="1" required aria-describedby="drill-responders-hint" placeholder="예: 2" value="${escapeHTML(String(value))}"></label>
    <p class="small muted" id="drill-responders-hint">본인을 포함해 지금 바로 역할을 맡을 수 있는 사람 수를 입력하세요. 훈련을 마치면 사람별 권장 역할을 볼 수 있어요.</p>`;
}
function readResponderCount(form){
  const input=form.elements.responders;
  const count=siteNumber(input.value,1);
  if(count===null){
    input.setCustomValidity('1부터 10000까지 숫자로 인원수를 입력하세요.');
    input.reportValidity();
  }
  return count;
}
function siteDetailFields(){
  return Object.entries(SITE_DRILL_FIELDS).map(([key,{label,options,min,example}])=>{
    const value=siteDrillDraft.details[key]??'';
    const name=`site-detail-${key}`;
    const field=options
      ? `<select name="${name}">${optionList(options,value,true)}</select>`
      : min!==undefined
        ? `<input type="number" name="${name}" min="${min}" max="10000" step="1" inputmode="numeric" placeholder="예: ${min===0?2:30}" value="${escapeHTML(String(value))}">`
        : `<input name="${name}" maxlength="100" placeholder="${example}" value="${escapeHTML(value)}">`;
    return `<label class="field">${label}${field}</label>`;
  }).join('');
}
