const shelterFilters={region:'all',time:'now',day:'all',extended:false,restricted:false,access:false,limit:SHELTER_PAGE_SIZE};
const erFilters={district:'all',query:''};
let shelterDevice='all';
let shelterAdvancedOpen=null;
const FINDER_LOCATE_ACTION={'emergency-finder':'er-locate','aed-finder':'aed-locate',nearby:'shelter-locate','water-events':'water-locate','water-need':'water-need-locate'};
const finderLocation={position:null,measuredAt:null,pending:false,request:0,message:'',manualOpen:false,query:'',searched:'',matches:[]};
const isFinderPage=page=>Object.hasOwn(FINDER_LOCATE_ACTION,page);
const validPosition=point=>!!point&&Number.isFinite(point.lat)&&Number.isFinite(point.lng)&&Math.abs(point.lat)<=90&&Math.abs(point.lng)<=180;
function straightDistance(km){
  return `직선거리 약 ${km<1?`${Math.round(km*1000)}m`:`${km.toFixed(1)}km`}`;
}
const preferredMap=()=>typeof store.prefs.mapProvider==='string'&&Object.hasOwn(MAP_PROVIDERS,store.prefs.mapProvider)?store.prefs.mapProvider:'ask';
function mapPlatform(){
  if(/Android/i.test(navigator.userAgent))return 'android';
  if(/iPhone|iPad|iPod/i.test(navigator.userAgent)||(/Macintosh/i.test(navigator.userAgent)&&navigator.maxTouchPoints>1))return 'ios';
  return 'desktop';
}
const mapParams=params=>new URLSearchParams(params).toString().replaceAll('+','%20');
const mapCoordinates=({lat,lng})=>`${lat.toFixed(6)},${lng.toFixed(6)}`;
function mapIntent(app,packageId,fallback){
  const [scheme,path]=app.split('://');
  return `intent://${path}#Intent;scheme=${scheme};package=${packageId};S.browser_fallback_url=${encodeURIComponent(fallback)};end`;
}
function mapLinks(provider,{name,query,position,route},origin=finderLocation.position,platform=mapPlatform()){
  const point=validPosition(position)?position:null,start=validPosition(origin)?origin:null;
  const search=query||name,from=start?.label||'현재 위치';
  const driving=route==='drive';
  if(provider==='google'){
    // 대구에서는 Google 지도의 장소 보기 링크를 제공합니다.
    const web=`https://www.google.com/maps/search/?${mapParams({api:1,query:point?mapCoordinates(point):search})}`;
    return {primary:web,web};
  }
  let web,app,packageId;
  if(provider==='kakao'){
    packageId='net.daum.android.map';
    const named=(label,coords)=>`${encodeURIComponent(label)},${mapCoordinates(coords)}`;
    const end=point?named(name,point):'';
    if(route&&point){
      web=start?`https://map.kakao.com/link/by/${driving?'car':'walk'}/${named(from,start)}/${end}`:`https://map.kakao.com/link/to/${end}`;
      app=`kakaomap://route?${mapParams({...(start?{sp:mapCoordinates(start)}:{}),ep:mapCoordinates(point),by:driving?'car':'foot'})}`;
    }else if(point){
      web=`https://map.kakao.com/link/map/${end}`;
      app=`kakaomap://look?${mapParams({p:mapCoordinates(point)})}`;
    }else{
      web=`https://map.kakao.com/link/search/${encodeURIComponent(search)}`;
      app=`kakaomap://search?${mapParams({q:search})}`;
    }
  }else{
    packageId='com.nhn.android.nmap';
    const appname=location.origin==='null'?'HEAT CHECK AI':`${location.origin}${location.pathname}`;
    web=`https://map.naver.com/p/search/${encodeURIComponent(search)}`;
    if(route&&point){
      if(start){
        const segment=(coords,label)=>encodeURIComponent(`${coords.lng.toFixed(6)},${coords.lat.toFixed(6)},${label.replaceAll(',',' ')},,ADDRESS_POI`);
        web=`https://way-m.map.naver.com/quick-path/${segment(start,from)}/${segment(point,name)}/-/${driving?'car':'walk'}/0`;
      }
      const args={...(start?{slat:start.lat,slng:start.lng,sname:from}:{}),dlat:point.lat,dlng:point.lng,dname:name,appname};
      app=`nmap://route/${driving?'car':'walk'}?${mapParams(args)}`;
    }else if(point){
      app=`nmap://place?${mapParams({lat:point.lat,lng:point.lng,name,appname})}`;
    }else{
      app=`nmap://search?${mapParams({query:search,appname})}`;
    }
  }
  const primary=platform==='android'?mapIntent(app,packageId,web):platform==='ios'?app:web;
  return {primary,web};
}
function mapProviderLink(label,href,kind='',extra=''){
  const tab=href.startsWith('https:')?' target="_blank" rel="noopener noreferrer"':'';
  return `<a class="btn ${kind}" href="${escapeHTML(href)}"${tab}${extra}>${escapeHTML(label)}</a>`;
}
function mapAction(label,{name,position=null,query='',route=false,kind=''}) {
  const target={name,position:validPosition(position)?{lat:position.lat,lng:position.lng}:null,query,route};
  const provider=preferredMap();
  if(provider==='ask'||(route&&provider==='google')){
    return `<button type="button" class="btn ${kind}" data-action="map-choose" data-value="${escapeHTML(JSON.stringify(target))}" aria-haspopup="dialog">${escapeHTML(label)}</button>`;
  }
  return mapProviderLink(label,mapLinks(provider,target).primary,kind);
}
function showMapChoices(value){
  let target;
  try{target=JSON.parse(value);}catch{return;}
  if(typeof target?.name!=='string')return;
  const platform=mapPlatform();
  showDialog(target.route?'길찾기에 사용할 지도':'어떤 지도에서 열까요?',`<div class="stack map-app-chooser">
    <p class="muted small">${escapeHTML(target.name)}</p>
    <label class="check-row"><input type="checkbox" id="remember-map-provider">이 기기에서 선택한 지도를 기본으로 사용</label>
    <div class="stack">${Object.entries(MAP_PROVIDERS).filter(([id])=>id!=='ask').map(([id,name])=>{
      const {primary,web}=mapLinks(id,target,finderLocation.position,platform);
      const label=target.route&&id==='google'?`${name}에서 장소 보기`:name;
      const remember=` data-map-provider="${id}"`;
      return `<div class="map-app-row">${mapProviderLink(label,primary,'secondary',remember)}
        ${primary!==web?mapProviderLink('웹으로 보기',web,'',` aria-label="${name} 웹으로 보기"${remember}`):''}
      </div>`;
    }).join('')}</div>
    ${platform==='desktop'?'':'<p class="muted small">앱이 열리지 않으면 웹으로 볼 수 있어요.</p>'}
    ${target.route?`<p class="muted small">${target.route==='drive'?'자동차':'도보'} 길찾기는 카카오맵과 네이버지도에서 확인할 수 있어요. Google 지도에서는 목적지 위치를 열어요.</p>`:''}
  </div>`);
}
function finderRouteButton(name,destination){
  return validPosition(destination)?mapAction(finderLocation.position?'도보 길찾기':'길찾기',{name,position:destination,route:true,kind:'secondary'}):'';
}
function finderControls(locate,forget,label='내 위치에서 가까운 순',id=''){
  const {position,pending,message,measuredAt}=finderLocation;
  const origin=position?(position.label||`${waterReportedTime(measuredAt)} GPS 위치 기준`):'';
  const caption=pending?'현재 위치를 확인하고 있어요.':position?`${origin} · 가까운 직선거리순${message?` · ${message}`:''}`:message||'출발지를 고르면 가까운 순서와 거리를 볼 수 있어요.';
  const gpsLabel=position?(position.label?'GPS 위치 사용':'위치 새로고침'):label;
  return `<div class="stack finder-controls">
    <div class="actions">${button(pending?'위치 확인 중':gpsLabel,locate,{kind:position?'secondary':'primary',mark:'pin',disabled:pending})}</div>
    <div class="actions">
      <button type="button" class="btn secondary" data-action="finder-manual" aria-expanded="${finderLocation.manualOpen}"${finderLocation.manualOpen?' aria-controls="finder-search"':''}>위치 직접 입력</button>
      <button type="button" class="btn secondary" data-action="finder-map" aria-haspopup="dialog">지도에서 고르기</button>
      ${position||pending?button('위치 사용 끄기',forget):''}
    </div>
    <p${id?` id="${id}"`:''} class="small muted" role="status">${escapeHTML(caption)}</p>
    ${finderLocation.manualOpen?finderSearchHTML():''}
    <div class="finder-map-settings"><button type="button" data-action="settings-map" class="plain-setting" aria-haspopup="dialog">지도 앱 설정</button><span class="small muted">${MAP_PROVIDERS[preferredMap()]}</span></div>
    ${position?'<p class="small muted">출발지는 이 탭에서만 사용해요. 길찾기를 열면 출발지와 목적지가 선택한 지도 서비스에 전달돼요.</p>':''}
  </div>`;
}
