let finderPlaces;
function normalizeFinderText(value){
  return value.normalize('NFKC').toLowerCase().replace(/대구광역시|대학교/g,word=>word==='대학교'?'대':'').replace(/경대(?=\s*(?:정문|북문|서문|동문|남문))/g,'경북대').trim();
}
const compactFinderText=value=>value.replace(/[^\p{L}\p{N}-]/gu,'');
function finderPlaceIndex(){
  if(finderPlaces)return finderPlaces;
  const places=[
    {label:'경북대학교 대구캠퍼스',description:'북구 대학로 80',type:'대학교',lat:35.8906491,lng:128.6121753},
    ...DAEGU_SHELTER_ROWS.filter(row=>row[9]).map(row=>({
      label:row[1],description:row[2],type:'등록 시설',lat:row[9][0],lng:row[9][1]
    })),
    ...DAEGU_EMERGENCY_ROOMS.map(({name:label,district,address,lat,lng})=>({label,description:`${district} ${address}`,type:'응급실 운영 병원',lat,lng})),
    ...WATER_ACCESS_FOUNTAINS.map(([,label,description,lat,lng])=>({label,description,type:'공원',lat,lng})),
    ...WATER_ACCESS_STORES.map(([,label,description,lat,lng])=>({label,description,type:'상점',lat,lng})),
    ...DAEGU_FINDER_STOPS.trim().split('\n').map(row=>{
      const [label,description,lat,lng]=row.split('|');
      return {label,description,type:'버스 정류장',lat:Number(lat),lng:Number(lng)};
    })
  ];
  const unique=new Map();
  for(const place of places){
    if(!validPosition(place))continue;
    const name=compactFinderText(normalizeFinderText(place.label));
    const address=normalizeFinderText(place.description).replace(/\s*\(.*/,''),key=`${name}|${place.lat.toFixed(5)}|${place.lng.toFixed(5)}`;
    if(!unique.has(key))unique.set(key,{...place,name,address,lookup:compactFinderText(address)});
  }
  finderPlaces=[...unique.values()];
  return finderPlaces;
}
function finderSearch(query){
  const coordinate=query.match(/^\s*(-?\d{1,2}\.\d+)\s*[, ]\s*(-?\d{1,3}\.\d+)\s*$/);
  if(coordinate){
    const lat=Number(coordinate[1]),lng=Number(coordinate[2]);
    return validPosition({lat,lng})?[{label:'직접 입력한 좌표',description:`${lat.toFixed(5)}, ${lng.toFixed(5)}`,lat,lng,type:'좌표'}]:[];
  }
  const normalized=normalizeFinderText(query);
  const key=compactFinderText(normalized);
  if(key.length<2)return [];
  const tokens=normalized.split(/\s+/).map(compactFinderText).filter(Boolean);
  const streetNumber=normalized.match(/(?:로|길)\s*(\d+(?:-\d+)?)\s*$/)?.[1];
  const places=view==='aed-finder'?finderPlaceIndex().concat(aedOriginIndex):finderPlaceIndex();
  return places.map(place=>{
    const {name,lookup,address,type}=place;
    if(name===key)return {place,score:0};
    if(streetNumber&&address.match(/(?:로|길)\s*(\d+(?:-\d+)?)\s*$/)?.[1]!==streetNumber)return null;
    if(lookup===key)return {place,score:1};
    if(name.startsWith(key))return {place,score:type==='버스 정류장'?2:3};
    if(name.includes(key))return {place,score:4};
    if(lookup.includes(key))return {place,score:5};
    if(tokens.length>1&&tokens.every(token=>name.includes(token)||lookup.includes(token)))return {place,score:6};
    return null;
  }).filter(Boolean).sort((a,b)=>a.score-b.score||a.place.label.length-b.place.label.length||a.place.label.localeCompare(b.place.label,'ko')).slice(0,6).map(row=>row.place);
}
function finderSearchHTML(){
  const {query,searched,matches}=finderLocation;
  const results=searched?`<div id="finder-matches" class="stack">
    <p id="finder-match-status" class="small" role="status" tabindex="-1">${escapeHTML(searched)} · ${matches.length?`후보 ${matches.length}곳`:'일치하는 장소를 찾지 못했어요. 다른 이름으로 검색하거나 지도에서 지점을 골라 보세요.'}</p>
    ${matches.length?`<ul class="finder-matches">${matches.map((place,index)=>`<li>
      <div><strong>${escapeHTML(place.label)}</strong><p class="small muted">${escapeHTML(place.type)} · ${escapeHTML(place.description)}</p></div>
      <div class="actions">${button('지도 확인','finder-map',{value:String(index),title:`${place.label} 지도 확인`})}${button('선택','finder-pick',{kind:'secondary',value:String(index),title:`${place.label} 선택`})}</div>
    </li>`).join('')}</ul>`:`<p class="small">${mapAction('지도 앱에서 이름 검색',{name:searched})}</p>`}
  </div>`:'';
  return `<div id="finder-search" class="finder-search stack">
    <form id="finder-search-form" class="stack">
      <label class="field" for="finder-query">출발지 이름 또는 주소</label>
      <div class="finder-query-row"><input id="finder-query" name="finder-query" type="search" value="${escapeHTML(query)}" placeholder="예: 경북대 정문, 북구 대학로 80" maxlength="100" autocomplete="off" required aria-describedby="finder-search-hint">
      <button class="btn secondary" type="submit">검색</button></div>
      <p id="finder-search-hint" class="small muted">대구 정류장, 등록 시설, 공원, 상점에서 찾을 수 있어요. <a href="https://www.data.go.kr/data/15050946/fileData.do" target="_blank" rel="noopener noreferrer">정류장 위치 출처</a></p>
    </form>${results}
  </div>`;
}
function chooseFinderPosition(position,resetRegion=true){
  cancelFinderRequest();
  finderLocation.position=position;
  finderLocation.measuredAt=Date.now();
  finderLocation.message='';
  if(resetRegion){
    shelterFilters.region=waterDistrict=waterNeedDistrict='all';
    erFilters.district='all';
    aedFilters.district='all';
    resetWaterNeedLimits();
  }
  shelterFilters.limit=SHELTER_PAGE_SIZE;
  aedFilters.limit=AED_PAGE_SIZE;
}
function applyFinderPosition(position){
  if(!validPosition(position)||!isFinderPage(view))return;
  chooseFinderPosition({lat:position.lat,lng:position.lng,label:position.label});
  Object.assign(finderLocation,{manualOpen:false,query:'',searched:'',matches:[]});
  render(false);
  if(view==='nearby'&&shelterFilters.time==='now')focusShelterResults();
  else focusSection(view==='aed-finder'&&aedDirectory?$('#aed-count'):$('.finder-controls [role="status"]'),'nearest');
}
let finderMapLoad,disposeFinderMap;
function loadFinderMap(){
  if(finderMapLoad)return finderMapLoad;
  const src='https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet';
  const style=Object.assign(document.createElement('link'),{
    rel:'stylesheet',href:`${src}.css`,integrity:'sha256-p4NxAoJBhIIN+hmNHrzRCf9tD/miZyoHS5obTRR9BMY=',crossOrigin:'anonymous'
  });
  const script=Object.assign(document.createElement('script'),{
    src:`${src}.js`,integrity:'sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo=',crossOrigin:'anonymous'
  });
  finderMapLoad=Promise.all([style,script].map(element=>new Promise((resolve,reject)=>{
    const timeout=setTimeout(reject,10000);
    const settle=callback=>()=>{clearTimeout(timeout);callback();};
    element.addEventListener('load',settle(resolve),{once:true});
    element.addEventListener('error',settle(reject),{once:true});
    document.head.append(element);
  }))).then(()=>window.L).catch(error=>{
    style.remove();script.remove();finderMapLoad=null;
    throw error;
  });
  return finderMapLoad;
}
function clearFinderMap(){
  disposeFinderMap?.();
  disposeFinderMap=null;
}
async function openFinderMap(index=''){
  if(!isFinderPage(view))return;
  const candidate=index===''?null:finderLocation.matches[Number(index)];
  const origin=candidate||finderLocation.position;
  showDialog('지도에서 출발지 고르기',`<div class="stack finder-map-dialog">
    <p id="finder-map-hint" class="small">지도를 움직이거나 두 손가락으로 확대하세요. 원하는 곳을 터치하거나 핀을 끌어서 위치를 조정할 수 있어요.</p>
    <div id="finder-map" class="finder-map" role="region" aria-label="출발지 지도" aria-describedby="finder-map-hint"></div>
    <p id="finder-map-status" class="small" role="status">지도를 불러오고 있어요.</p>
    <div class="actions finder-map-actions"><button type="button" id="finder-map-center" class="btn secondary" disabled>지도 가운데 선택</button>
    <button type="button" id="finder-map-apply" class="btn primary" disabled>이 위치로 찾기</button></div>
    <p class="muted small">지도를 열면 화면에 보이는 지역의 지도 데이터를 OpenStreetMap에서 불러와요.</p>
  </div>`);
  const dialog=$('#dialog'), host=$('#finder-map'), status=$('#finder-map-status');
  const center=$('#finder-map-center'), apply=$('#finder-map-apply');
  let map,marker,selected=null,tileTimer;
  const active=()=>dialog.open&&host.isConnected;
  try{
    const L=await loadFinderMap();
    if(!active())return;
    map=L.map(host,{scrollWheelZoom:false,tapHold:false,maxZoom:19}).setView(origin?[origin.lat,origin.lng]:[35.8714,128.6014],origin?17:13);
    disposeFinderMap=()=>{clearTimeout(tileTimer);map.remove();};
    map.attributionControl.setPrefix(false);
    map.zoomControl.getContainer().querySelector('.leaflet-control-zoom-in').setAttribute('aria-label','지도 확대');
    map.zoomControl.getContainer().querySelector('.leaflet-control-zoom-out').setAttribute('aria-label','지도 축소');
    const pin=L.divIcon({className:'finder-map-pin',html:'<span></span>',iconSize:[44,44],iconAnchor:[22,40]});
    const updateStatus=()=>{
      const mapReady=!!host.querySelector('.leaflet-tile-loaded');
      const mapUnavailable=host.classList.contains('finder-map-unavailable');
      center.disabled=!mapReady;apply.disabled=!selected||!mapReady;
      if(mapUnavailable){status.textContent='지도 배경을 불러오지 못했어요. 연결을 확인하거나 위치 직접 입력으로 검색해 주세요.';return;}
      if(!mapReady){status.textContent='지도를 불러오고 있어요.';return;}
      status.textContent=selected?`${selected.label} · ${selected.lat.toFixed(5)}, ${selected.lng.toFixed(5)}`:'지도에서 지점을 터치하거나 가운데 지점을 선택하세요.';
    };
    const select=(point,label='지도에서 고른 지점')=>{
      const {lat,lng}=map.wrapLatLng(point);
      selected={lat,lng,label};
      if(marker)marker.setLatLng([lat,lng]);
      else {
        marker=L.marker([lat,lng],{icon:pin,draggable:true,title:'선택한 출발지 핀'}).addTo(map);
        marker.on('dragend',()=>select(marker.getLatLng()));
        marker.getElement().setAttribute('aria-label','선택한 출발지 핀');
      }
      updateStatus();
    };
    const watchTiles=()=>{
      clearTimeout(tileTimer);
      tileTimer=setTimeout(()=>{
        host.classList.toggle('finder-map-unavailable',!host.querySelector('.leaflet-tile-loaded'));
        updateStatus();
      },7000);
    };
    const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{
      maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a>'
    });
    tiles.on('loading',watchTiles);
    tiles.on('tileload',()=>{
      host.classList.remove('finder-map-unavailable');
      updateStatus();
    });
    tiles.on('load',()=>{
      clearTimeout(tileTimer);
      host.classList.toggle('finder-map-unavailable',!host.querySelector('.leaflet-tile-loaded'));
      updateStatus();
    });
    tiles.addTo(map);
    map.on('click',event=>{if(!center.disabled)select(event.latlng);});
    center.addEventListener('click',()=>select(map.getCenter()));
    apply.addEventListener('click',()=>{dismiss();applyFinderPosition(selected);});
    if(origin)select(L.latLng(origin.lat,origin.lng),origin.label||'현재 위치');
    requestAnimationFrame(()=>{if(active())map.invalidateSize({pan:false});});
  }catch{
    if(!active())return;
    clearFinderMap();
    host.classList.add('finder-map-unavailable');
    status.textContent='지도를 불러오지 못했어요. 위치 직접 입력으로 장소 이름이나 위도, 경도를 검색할 수 있어요.';
  }
}
function cancelFinderRequest(){
  finderLocation.request++;
  finderLocation.pending=false;
}
function forgetFinderLocation(){
  cancelFinderRequest();
  Object.assign(finderLocation,{position:null,measuredAt:null,message:'위치 사용을 종료했어요.',manualOpen:false,query:'',searched:'',matches:[]});
  render(false,`[data-action="${FINDER_LOCATE_ACTION[view]}"]`);
}
function locateFinder(){
  if(!isFinderPage(view)||finderLocation.pending)return;
  const request=++finderLocation.request, hadPosition=!!finderLocation.position;
  const refresh=()=>render(false,`[data-action="${FINDER_LOCATE_ACTION[view]}"]`);
  const finish=(position,message='')=>{
    if(finderLocation.request!==request||!isFinderPage(view))return;
    finderLocation.pending=false;finderLocation.message=message;
    if(position){
      chooseFinderPosition(position,!hadPosition||!!finderLocation.position.label);
      if(view==='water-events'&&!hadPosition&&waterMode==='today')waterMode='now';
    }
    refresh();
    if(position&&view==='aed-finder'&&aedDirectory)focusSection($('#aed-count'));
    if(position&&view==='nearby'&&shelterFilters.time==='now')focusShelterResults();
  };
  if(!window.isSecureContext||!navigator.geolocation){finish(null,'이 환경에서 GPS를 사용할 수 없어요. 위치를 직접 입력하거나 지도에서 골라 주세요.');return;}
  finderLocation.pending=true;finderLocation.message='';refresh();
  navigator.geolocation.getCurrentPosition(({coords})=>{
    const position={lat:coords.latitude,lng:coords.longitude};
    if(validPosition(position))finish(position);
    else finish(null,'GPS 위치를 읽지 못했어요. 위치를 직접 입력하거나 지도에서 골라 주세요.');
  },()=>finish(null,hadPosition?'GPS를 확인하지 못해 기존 출발지를 사용해요.':'GPS를 확인하지 못했어요. 위치를 직접 입력하거나 지도에서 골라 주세요.'),{timeout:8000,maximumAge:30000});
}
function shelterAccessActive(filters=shelterFilters){
  return !!filters.access||Object.keys(SHELTER_ACCESS_LABELS).some(key=>filters[key]);
}
function shelterAdvancedActive(){
  return shelterAccessActive()||shelterFilters.extended||shelterFilters.restricted;
}

function shelterTime(minutes){return `${String(Math.floor(minutes/60)).padStart(2,'0')}:${String(minutes%60).padStart(2,'0')}`;}
function shelterHours(row,includeExtended){
  const [, , , , , regular,extra,night]=row;
  return [['기본',regular],...(includeExtended?[['특보 시 추가',extra],['특보 시 연장',night]]:[])].filter(([,hours])=>!!hours);
}
function matchesShelterHours(hours,filters,now=Date.now()){
  const [from,to,days]=hours;
  if(filters.time==='now'){
    const local=new Date(now+9*3600000), minute=local.getUTCHours()*60+local.getUTCMinutes();
    const day=(local.getUTCDay()+6)%7, previous=(day+6)%7;
    if(to<from)return !!((days&(1<<day))&&minute>=from||(days&(1<<previous))&&minute<to);
    return !!((days&(1<<day))&&minute>=from&&minute<to);
  }
  if(filters.day!=='all'&&!(days&(1<<Number(filters.day))))return false;
  if(filters.time==='all')return true;
  const close=to<from?to+1440:to;
  return close>Number(filters.time);
}
function sheltersFor(filters,rows=DAEGU_SHELTER_ROWS,now=Date.now()){
  return rows.flatMap(row=>{
    const [region, ,address, , publicAccess]=row;
    if((filters.region!=='all'&&filters.region!==region)||(!filters.restricted&&!publicAccess))return [];
    const access=SHELTER_ACCESS[address];
    if((filters.access&&!access)||Object.keys(SHELTER_ACCESS_LABELS).some(key=>filters[key]&&!access?.[key]))return [];
    const schedules=shelterHours(row,filters.extended);
    const matches=schedules.filter(([,hours])=>matchesShelterHours(hours,filters,now));
    if(!matches.length&&(filters.time!=='all'||filters.day!=='all'||schedules.length))return [];
    const regular=matches.some(([kind])=>kind==='기본');
    const coordinates=row[9];
    const distance=coordinates&&filters.position?waterDistance(filters.position,{lat:coordinates[0],lng:coordinates[1]}):Infinity;
    return [{row,matches,regular,access,distance}];
  }).sort((a,b)=>{
    if(a.distance!==b.distance)return a.distance-b.distance;
    const order=Number(b.regular)-Number(a.regular);
    return order||DAEGU_DISTRICTS.indexOf(a.row[0])-DAEGU_DISTRICTS.indexOf(b.row[0])||a.row[1].localeCompare(b.row[1],'ko');
  });
}
function shelterScheduleLine(label,[from,to,days]){
  const dayText=SHELTER_DAYS.filter((_,i)=>days&(1<<i)).join('·');
  const hours=from===0&&to===1440?'24시간':`${shelterTime(from)}–${to<from?'다음 날 ':''}${shelterTime(to)}`;
  return `<li><b>${label} ${hours}</b>${dayText?` <span class="muted">${dayText}</span>`:' <span class="muted">요일 미기재</span>'}</li>`;
}
function shelterAccessFacts(access){
  if(!access)return '<p class="small"><strong>휠체어 접근성 미확인</strong> · 공개 자료에 확인된 항목이 없어요.</p>';
  const fields=Object.entries(SHELTER_ACCESS_LABELS);
  const confirmed=fields.filter(([key])=>access[key]);
  const unknown=fields.filter(([key])=>!access[key]).map(([,label])=>label);
  return `<div class="shelter-access-facts stack"><h4>휠체어 이용 조건</h4>
    <p class="small shelter-entry-status"><strong>${access.stepFree?'자료에 단차 없는 출입구 표기':'단차 없는 출입구 미확인'}</strong>${access.stepFree?` · ${escapeHTML(access.stepFree)}`:''}</p>
    <dl>${confirmed.filter(([key])=>key!=='stepFree').map(([key,label])=>`<div><dt>${label}</dt><dd>${escapeHTML(access[key])}</dd></div>`).join('')}</dl>
    <details class="shelter-access-more">
      <summary>미확인 정보와 출처</summary>
      <p class="small muted">${unknown.length?`자료 미확인 · ${unknown.join(', ')}`:''}</p>
      <p class="small muted">현장 확인일은 제공되지 않아요. 당일 출입구와 장비 이용은 시설에 문의할 수 있어요.</p>
      <p class="small muted">출입문 유효 폭, 내부 회전 공간, 승강기 크기·허용 하중, 충전기와 기기의 호환 여부는 시설에 확인해 주세요.</p>
      <div class="shelter-links">${access.source?external('시설 접근성 자료',access.source):''}${access.arrivalSource?external('도서관의 휠체어 교통 안내',access.arrivalSource):''}${access.charging?external('대구시 충전기 자료',SHELTER_CHARGER_SOURCE):''}</div>
    </details>
    ${access.phone?`<div class="shelter-links"><a href="tel:${access.phone}">시설에 문의 ${access.phone}</a></div>`:''}
  </div>`;
}
function shelterCard(entry,closest=false){
  const {row,matches,regular,access,distance}=entry;
  const [region,name,address,facility,publicAccess, , , ,phone,coordinates]=row;
  const position=coordinates?{lat:coordinates[0],lng:coordinates[1]}:null;
  return `<article class="card stack shelter-card${closest?' water-closest':''}"><div class="actions">${pill(region)}${pill(publicAccess?'누구나 이용 안내':'이용 대상 확인',publicAccess?'green':'orange')}${matches.length&&!regular?pill('특보 시 운영표','orange'):''}${closest?pill('거리순 첫 장소','green'):''}${Number.isFinite(distance)?pill(straightDistance(distance)):finderLocation.position?pill('좌표 미등록'):''}</div><h3>${escapeHTML(name)}</h3><p class="muted small">대구광역시 ${escapeHTML(address)} · ${escapeHTML(facility)}</p>
  <div class="stack facility-verification"><p class="small"><strong>${matches.length?'등록 운영표':'운영시간 미확인'}</strong> · 현장 개방 미확인</p>
    ${matches.length?`<ul class="shelter-hours">${matches.map(([label,hours])=>shelterScheduleLine(label,hours)).join('')}</ul>`:''}
    <p class="small muted">국민안전24 자료 확인 · <time datetime="${SHELTER_DATA_CHECKED}">${SHELTER_DATA_CHECKED}</time></p>
    ${phone?`<a class="btn secondary" href="tel:${phone}" aria-label="${escapeHTML(name)} 운영 문의 ${phone}">운영 문의 ${phone}</a>`:''}
  </div>
  ${shelterAccessFacts(access)}
  <div class="actions">${shelterAccessActive()&&position?mapAction('일반 도보 길찾기',{name,position,route:true,kind:'secondary'}):finderRouteButton(name,position)}${mapAction('지도 보기',{name,position,query:`대구광역시 ${address}`})}</div></article>`;
}

const SHELTER_NEARBY_KM=1;
const DAEGU_LIBRARY_HOURS='https://library.daegu.go.kr/dgulib/html.do?menu_idx=20';
// 일반 종합자료실 운영표와 정기휴관일은 대구통합도서관에서 확인했습니다.
// 위치는 동일 시설의 국민안전24 등록 주소·좌표를 사용합니다.
const SHELTER_ALTERNATIVE_LIBRARIES=[
  ['범어도서관','beomeo/html/bemeoCalendar3.do?menu_idx=18',22,'every'],
  ['고산도서관','gosan/html/bemeoCalendar3.do?menu_idx=18',22,'every'],
  ['구수산도서관','bukgs/html.do?menu_idx=18',22,'even'],
  ['달성군립도서관','dalseonglib/html.do?menu_idx=18',22,'every']
];
function shelterAlternativeLibraries(filters,available,now){
  if(!filters.position)return [];
  const clock=new Date(now+9*3600000);
  const weekday=clock.getUTCDay(), minutes=clock.getUTCHours()*60+clock.getUTCMinutes();
  const week=Math.ceil(clock.getUTCDate()/7);
  const sourceByName=new Map(DAEGU_SHELTER_ROWS.filter(row=>row[9]).map(row=>[row[1],row]));
  const availableNames=new Set(available.map(entry=>entry.row[1]));
  return SHELTER_ALTERNATIVE_LIBRARIES.flatMap(([name,source,end,closedMonday])=>{
    const row=sourceByName.get(name);
    if(!row||availableNames.has(name)||(filters.region!=='all'&&row[0]!==filters.region))return [];
    if(weekday===1&&(closedMonday==='every'||week===2||week===4))return [];
    const close=weekday===0||weekday===6?17:end;
    if(minutes<540||minutes>=close*60)return [];
    const position={lat:row[9][0],lng:row[9][1]};
    const distance=waterDistance(filters.position,position);
    return distance<=SHELTER_NEARBY_KM?[{name,address:row[2],source,close,position,distance}]:[];
  }).sort((a,b)=>a.distance-b.distance).slice(0,2);
}
function shelterFallback(filters,rows,now){
  const open=rows.filter(entry=>entry.regular&&entry.row[4]);
  if(filters.position?open.some(entry=>entry.distance<=SHELTER_NEARBY_KM):open.length)return '';
  const libraries=shelterAlternativeLibraries(filters,open,now);
  const knownDistances=open.filter(entry=>Number.isFinite(entry.distance));
  const away=filters.position?knownDistances[0]:null;
  const area=filters.region==='all'?'대구광역시':`대구광역시 ${filters.region}`;
  const scope=filters.position?`출발지에서 직선 ${SHELTER_NEARBY_KM}km 안`:'선택한 지역';
  return `<section class="card stack shelter-alternative" aria-labelledby="shelter-alternative-heading">
    <div class="stack">${coachReadout('<h3 id="shelter-alternative-heading">가까운 쉼터가 없을 때</h3>')}
    <p>${scope}에 현재 시간과 검색 조건에 맞는 일반 개방 쉼터를 운영표에서 찾지 못했어요.</p></div>
    <div class="stack shelter-cool-first"><h4>지금 더위가 힘들다면</h4>
      <p class="small">활동을 멈추고 가까운 시원한 실내나 그늘에서 쉬며 몸을 식히세요. 의식이 흐리거나 쓰러진 사람이 반응하지 않으면 즉시 119에 전화하세요.</p>
      <div class="actions">${call119()}${button('증상별 행동 보기','field-now',{kind:'secondary'})}</div>
    </div>
    <div class="stack"><h4>대체 실내 장소 찾기</h4>
      <p class="small muted">${libraries.length?'공공도서관 일반 자료실 기준이에요. 방문 전에 휴관·냉방·이용 조건을 확인하세요.':`지도에서 ${filters.position?'출발지 주변의':'선택 지역의'} 공공도서관이나 냉방 실내 장소를 확인해 보세요. 출입과 냉방 여부는 장소별로 확인하세요.`}${shelterAccessActive(filters)?' 대체 장소의 휠체어 이용 조건은 확인이 필요해요.':''}</p>
      ${libraries.map(({name,address,source,close,position,distance})=>`<article class="stack facility-verification"><h4>${escapeHTML(name)}</h4><p class="small">${escapeHTML(address)} · ${straightDistance(distance)}</p><p class="small">일반 자료실 09:00–${shelterTime(close*60)} · 현장 개방 미확인</p><div class="actions">${mapAction('지도에서 위치 보기',{name,position})}${external('도서관 운영 안내','https://library.daegu.go.kr/'+source)}</div></article>`).join('')}
      <div class="actions">${shelterLibrarySearch(area,filters.position)}${button('지금 마실 물 찾기','water-need',{kind:'secondary',mark:'drop'})}</div>
      <div class="shelter-links">${external('대구 공공도서관 운영·휴관일',DAEGU_LIBRARY_HOURS)}</div>
    </div>
    ${away?`<div class="stack"><h4>조금 더 먼 쉼터</h4><p class="small">${escapeHTML(away.row[1])} · ${straightDistance(away.distance)}. 이동할 수 있는 상태라면 개방 여부를 먼저 확인하세요.</p><div class="actions">${button('해당 쉼터 보기','shelter-farther',{kind:'secondary',value:rows.indexOf(away)})}</div></div>`:''}
  </section>`;
}
function shelterLibrarySearch(area,position){
  if(position&&!position.label&&area==='대구광역시'){
    const href=`https://www.google.com/maps/search/${encodeURIComponent('공공도서관')}/@${mapCoordinates(position)},15z`;
    return mapProviderLink('주변 도서관 지도 검색',href,'secondary');
  }
  return mapAction('도서관 지도 검색',{name:'공공도서관',query:`${area} ${position?.label||''} 공공도서관`.trim(),kind:'secondary'});
}
function focusShelterResults(){
  focusSection($('#shelter-alternative-heading')||$('#shelter-count'));
}
function focusFartherShelter(value){
  const index=Number(value);
  if(!Number.isInteger(index)||index<0)return;
  if(index>=shelterFilters.limit){
    shelterFilters.limit=index+1;
    updateShelterResults();
  }
  focusSection(document.querySelectorAll('#shelter-results .shelter-card')[index]);
}

function shelterResults(now=Date.now()){
  const filters={...shelterFilters,position:finderLocation.position};
  const rows=sheltersFor(filters,DAEGU_SHELTER_ROWS,now), shown=rows.slice(0,filters.limit);
  const alternative=filters.time==='now'?shelterFallback(filters,rows,now):'';
  const wheelchairs=shelterAccessActive();
  const summary=rows.length?`${rows.length.toLocaleString('ko-KR')}곳 · ${shown.length.toLocaleString('ko-KR')}곳 표시${finderLocation.position?' · 직선거리순':''}`:wheelchairs?'현재 선택한 조건을 모두 확인한 쉼터가 없어요.':'선택 조건에 맞는 운영 안내를 찾지 못했습니다.';
  const empty=wheelchairs?`<div class="card stack"><p class="small muted">시설에 조건이 갖춰져 있는지 공개 자료에서 확인하지 못했거나 현재 지역·시간과 일치하는 시설이 없어요.</p><div class="actions">
    ${shelterFilters.region!=='all'||shelterFilters.time!=='all'||shelterFilters.day!=='all'?button('대구 전체·전체 시간 보기','shelter-access-broaden',{kind:'secondary'}):''}
    ${button('단차 없는 출입구만 검색','shelter-access-entrances')}
    ${button('접근성 미확인 시설도 보기','shelter-access-unconfirmed')}
  </div></div>`:`<div class="notice warn">${icon('info')}<div>다른 구·군이나 시간대를 선택해 보세요. 운영시간이 미기재된 시설은 시간 필터에서 제외합니다.</div></div>`;
  return alternative+coachReadout(`<p id="shelter-count" class="shelter-count" role="status">${summary}</p>`)
    +`${shelterFilters.time==='now'?'<p class="small muted">현재 한국시간과 등록 운영표로 찾은 결과입니다. 계절·공휴일·현장 개방 여부를 확인하세요.</p>':''}`
    +`${wheelchairs&&shown.length?'<p class="small muted">일반 도보 길찾기에서 경로의 턱·경사·계단 여부는 확인되지 않아요.</p>':''}`
    +`${shown.length?`<div class="shelter-grid">${shown.map((row,index)=>shelterCard(row,index===0&&Number.isFinite(row.distance))).join('')}</div>`:alternative&&!wheelchairs?'':empty}`
    +`${rows.length>shown.length?`<div class="actions">${button('쉼터 더 보기','shelters-more',{kind:'secondary'})}</div>`:''}`;
}
function shelterAccessFilters(){
  return `<fieldset id="shelter-access" class="shelter-time stack"><legend>휠체어 이용 조건</legend>
    <label class="field">이용하는 이동기기<select name="shelter-device" aria-describedby="shelter-device-guidance">${optionList(SHELTER_ACCESS_DEVICES,shelterDevice)}</select></label>
    <p id="shelter-device-guidance" class="small muted" aria-live="polite">${SHELTER_DEVICE_GUIDANCE[shelterDevice]}</p>
    <label class="check-row"><input type="checkbox" name="shelter-access" ${shelterFilters.access?'checked':''}>접근성 자료가 있는 쉼터만</label>
    ${SHELTER_ACCESS_GROUPS.map(([group,labels],index)=>`<details class="shelter-access-group"${index===0||Object.keys(labels).some(key=>shelterFilters[key])?' open':''}><summary>${group}</summary>
      <div class="shelter-access-options">${Object.entries(labels).map(([key,label])=>`<label class="check-row small"><input type="checkbox" name="shelter-${key}" ${shelterFilters[key]?'checked':''}>${label}</label>`).join('')}</div>
    </details>`).join('')}
    <p class="small muted">선택한 항목이 모두 자료에서 확인된 쉼터를 보여줘요. 이동기기를 바꾸면 확인할 항목 안내가 바뀌어요.</p>
    <div class="shelter-links">${external('대구 저상버스 운행 안내',SHELTER_ACCESS_TRANSPORT.bus)}${external('나드리콜 이용 대상·신청',SHELTER_ACCESS_TRANSPORT.taxi)}</div>
  </fieldset>`;
}
function shelterFinder(){
  const areas={all:'대구광역시 전체',...Object.fromEntries(DAEGU_DISTRICTS.map(area=>[area,area]))};
  const weekdays=Object.entries(SHELTER_DAYS).map(([i,name])=>`<option value="${i}" ${shelterFilters.day===i?'selected':''}>${name}요일</option>`).join('');
  return `<section class="stack" aria-labelledby="shelter-heading"><div class="card stack"><h2 id="shelter-heading">대구 무더위쉼터 찾기</h2><p class="muted small">국민안전24의 2026년 등록 운영표입니다. 폭염 기간, 휴관일과 공휴일에 따라 달라질 수 있으니 방문 전 담당 부서에 확인하세요.</p>${finderControls('shelter-locate','shelter-forget','내 주변 쉼터 찾기','shelter-location')}<div class="form-grid compact-filters"><label class="field">대구 구·군<select name="shelter-region">${optionList(areas,shelterFilters.region)}</select></label><label class="field">요일<select name="shelter-day" ${shelterFilters.time==='now'?'disabled':''}>${optionList({all:shelterFilters.time==='now'?'오늘 기준':'요일 전체'},shelterFilters.day)}${weekdays}</select></label></div><fieldset class="shelter-time"><legend>운영 시간대</legend><div class="radio-row">${[['now','지금 · 운영표 기준'],['960','16시 이후'],['1080','18시 이후'],['1200','20시 이후'],['all','전체 시간']].map(([value,label])=>`<label><input type="radio" name="shelter-time" value="${value}" ${shelterFilters.time===value?'checked':''}>${label}</label>`).join('')}</div></fieldset>
  <details id="shelter-advanced" ${(shelterAdvancedOpen??!compactScreen.matches)?'open':''}><summary>추가 검색 조건 <span id="shelter-advanced-status" class="muted small">${shelterAdvancedActive()?' · 적용 중':''}</span></summary><div class="stack"><div class="shelter-options"><label class="check-row small"><input type="checkbox" name="shelter-extended" ${shelterFilters.extended?'checked':''}>폭염특보 시 추가·연장 운영 포함</label><label class="check-row small"><input type="checkbox" name="shelter-restricted" ${shelterFilters.restricted?'checked':''}>이용 대상 확인이 필요한 시설 포함</label></div>
  ${shelterAccessFilters()}
  </div></details><div class="shelter-filter-footer">${button('검색 결과 보기','shelter-results',{kind:'secondary'})}<p class="small muted">${sourceLink('map')}</p></div></div><div id="shelter-results" class="stack">${shelterResults()}</div></section>`;
}
function updateShelterResults(){
  const target=$('#shelter-results');
  if(target){target.innerHTML=shelterResults();setLive([$('#shelter-alternative-heading')?.textContent,$('#shelter-count').textContent].filter(Boolean).join(' · '));}
  const status=$('#shelter-advanced-status');
  if(status)status.textContent=shelterAdvancedActive()?' · 적용 중':'';
}
function openShelterAccessSearch({entrancesOnly=false,showFilters=false}={}){
  Object.assign(shelterFilters,{region:'all',time:'all',day:'all',limit:SHELTER_PAGE_SIZE});
  shelterAdvancedOpen=true;
  if(entrancesOnly){
    for(const key of Object.keys(SHELTER_ACCESS_LABELS))shelterFilters[key]=key==='stepFree';
    Object.assign(shelterFilters,{access:true,restricted:false,extended:false});
  }
  if(view!=='nearby')navigate('nearby');
  else render(false);
  focusSection($(showFilters?'#shelter-access':'#shelter-results'));
}
