function emergencyResults(){
  const position=finderLocation.position;
  const query=compactFinderText(normalizeFinderText(erFilters.query));
  const matches=DAEGU_EMERGENCY_ROOMS.filter(({district,name,address})=>
    (erFilters.district==='all'||district===erFilters.district)&&
    (!query||compactFinderText(normalizeFinderText(`${name} ${district} ${address}`)).includes(query))
  ).map(room=>({room,distance:position?waterDistance(position,room):null}));
  if(position)matches.sort((a,b)=>a.distance-b.distance);
  const sort=position?'가까운 직선거리순':'구·군 순';
  const scope=erFilters.district==='all'?'대구광역시':erFilters.district;
  const count=`${scope} ${matches.length}곳 · ${sort}`;
  return `${coachReadout(`<h2 id="er-count" class="result-section-title">${count}</h2>`)}${matches.length?matches.map(({room,distance})=>{
    const {district,name,address,phone,direct}=room;
    const officialSearch=new URL(SOURCES.emergency.href);
    officialSearch.searchParams.set('emogdesc',name.replace(/\s+/g,''));
    return `<article class="card stack er-card"><div><p class="small muted">${district}${distance===null?'':` · ${straightDistance(distance)}`}</p><h3>${escapeHTML(name)}</h3><p>${escapeHTML(`대구 ${district} ${address}`)}</p><p class="small muted">${direct?'응급실 직통':'병원 대표'} ${phone}</p></div>
      <div class="actions"><a class="btn secondary" href="tel:${phone}" aria-label="${escapeHTML(name)} ${direct?'응급실':'대표번호'} 전화하기">${icon('phone')} 전화</a>
      ${mapAction('길찾기',{name:`${name} 응급실`,position:room,route:'drive',kind:'secondary'})}
      ${external('E-Gen 병원 검색',officialSearch.href)}</div></article>`;
  }).join(''):`<div class="card stack"><p>${erFilters.district==='군위군'&&!query?'E-Gen 대구 목록에 군위군 소재 응급실이 없습니다. 대구 전체로 바꾸거나 E-Gen에서 인접 지역을 검색해 보세요.':'검색 조건에 맞는 응급실이 없어요. 구·군이나 병원명·주소를 바꿔 보세요.'}</p></div>`}`;
}
function updateEmergencyResults(){
  const target=$('#er-results');
  if(!target)return;
  target.innerHTML=emergencyResults();
  setLive($('#er-count').textContent);
}
