const AED_DAYS=['월','화','수','목','금','토','일','공휴일'];
const aedFilters={query:'',district:'all',scheduled:false,limit:AED_PAGE_SIZE};
let aedDirectory=null,aedLoading=false,aedLoadError=false,aedOriginIndex=[];

function aedTimeSlot(value){
  const match=value.match(/^(\d{2}):(\d{2})~(\d{2}):(\d{2})$/);
  if(!match)return null;
  const [,startHour,startMinute,endHour,endMinute]=match.map(Number);
  if(startHour>=24||endHour>=48||startMinute>=60||endMinute>=60)return null;
  const from=startHour*60+startMinute,end=endHour*60+endMinute;
  if(from===end)return null;
  const to=end<from?end+1440:end;
  const label=from===0&&to===1440?'24시간':`${shelterTime(from)}–${to>1440?'다음 날 ':''}${shelterTime(to>1440?to-1440:to)}`;
  return {from,to,label};
}
function aedLocalClock(date=new Date()){
  const korea=new Date(date.getTime()+9*60*60*1000);
  return {day:(korea.getUTCDay()+6)%7,minute:korea.getUTCHours()*60+korea.getUTCMinutes()};
}
function aedScheduledStatus(slots,{day,minute}){
  const today=slots[day],previousDay=(day+6)%7,previous=slots[previousDay];
  if(previous&&previous.to>1440&&minute<previous.to-1440)return {kind:'scheduled',day:previousDay,slot:previous};
  if(!today)return {kind:'unknown',day,slot:null};
  return {kind:minute>=today.from&&minute<today.to?'scheduled':'outside',day,slot:today};
}
const aedLookupKey=value=>compactFinderText(normalizeFinderText(value));
const aedStreetNumber=value=>normalizeFinderText(value).match(/(?:로|길)\s*(\d+(?:-\d+)?)(?=\s|$)/)?.[1];
function parseAedDirectory(data){
  if(!Array.isArray(data.records)||!data.records.length||!/^\d{4}-\d{2}-\d{2}$/.test(data.checkedOn))throw Error('AED 자료 형식이 다릅니다.');
  const origins=new Map();
  const records=data.records.map(([id,district,name,place,address,lat,lng,phone,timing,documentUrl])=>{
    const nameKey=aedLookupKey(name);
    const row={id,district,name,place,address,lat,lng,phone,slots:timing.split('|').map(aedTimeSlot),documentUrl,streetNumber:aedStreetNumber(address),
      key:aedLookupKey(`${name} ${place} ${address} ${district}`),nameKey};
    if(validPosition(row)){
      const key=`${nameKey}|${lat}|${lng}`;
      if(!origins.has(key))origins.set(key,{label:name,description:address,lat,lng,type:'AED 등록 기관',name:nameKey,address:normalizeFinderText(address).split('(')[0].trim(),lookup:aedLookupKey(address)});
    }
    return row;
  });
  aedOriginIndex=[...origins.values()];
  return {...data,records,byId:new Map(records.map(row=>[row.id,row]))};
}
async function loadAedDirectory(){
  if(aedDirectory||aedLoading)return;
  aedLoading=true;aedLoadError=false;
  updateAedResults();
  const request=new AbortController(),timeout=setTimeout(()=>request.abort(),8000);
  try{
    let raw=AED_EMBEDDED_DATA;
    if(raw)raw=JSON.parse(raw);
    else{
      const response=await fetch(new URL('./aed-daegu.json',location.href),{signal:request.signal});
      if(!response.ok)throw Error('AED 자료가 열리지 않습니다.');
      raw=await response.json();
    }
    aedDirectory=parseAedDirectory(raw);
  }catch{aedLoadError=true;}
  finally{
    clearTimeout(timeout);aedLoading=false;updateAedResults(true);
    const stamp=$('#aed-snapshot-note');if(stamp)stamp.textContent=aedSnapshotNote();
  }
}
function openAedFinder(){
  navigate('aed-finder');
  loadAedDirectory();
}
function aedOfficialRecord(row){
  if(row.documentUrl)return external('기관 설치 목록 원문',escapeHTML(row.documentUrl));
  const url=new URL('https://www.e-gen.or.kr/egen/get_aed_detail.do');
  url.searchParams.set('jsonSearchCondition',JSON.stringify({istYeaSno:row.id,loca:'13',sidoCode:'27',searchType:'general',currentPageNum:'1'}));
  return external('E-Gen 등록 원문',escapeHTML(url.href));
}
function rankedAedRecords(records,filters,position,clock){
  const normalized=normalizeFinderText(filters.query);
  const terms=normalized.split(/\s+/).map(aedLookupKey).filter(term=>term&&!['aed','자동심장충격기'].includes(term));
  const exact=terms.join(''),streetNumber=aedStreetNumber(normalized);
  return records.flatMap(row=>{
    if(filters.district!=='all'&&filters.district!==row.district)return [];
    if(streetNumber&&row.streetNumber!==streetNumber)return [];
    if(!terms.every(key=>row.key.includes(key)))return [];
    const status=aedScheduledStatus(row.slots,clock);
    if(filters.scheduled&&status.kind!=='scheduled')return [];
    const distance=position&&validPosition(row)?waterDistance(position,row):null;
    return [{row,distance,status,exact:!!exact&&row.nameKey.includes(exact)}];
  }).sort((a,b)=>(a.distance??Infinity)-(b.distance??Infinity)||Number(b.exact)-Number(a.exact)||a.row.name.localeCompare(b.row.name,'ko'));
}
function aedDaySchedule(slots){
  const groups=new Map();
  for(const [index,day] of AED_DAYS.entries()){
    const label=slots[index]?.label||'미확인';
    const bucket=groups.get(label)||[];
    bucket.push(day);groups.set(label,bucket);
  }
  return `<ul class="aed-schedules">${[...groups].map(([label,days])=>`<li><b>${days.join('·')}</b> ${label}</li>`).join('')}</ul>`;
}
function aedCard({row,distance,status}){
  const knownPosition=validPosition(row);
  const statusText={scheduled:'등록 시간대',outside:'등록 시간 밖',unknown:'이용시간 미확인'}[status.kind];
  const mapLabel=row.address.startsWith('대구')?row.address:`대구 ${row.address}`;
  return `<article class="card stack aed-card"><div class="actions aed-tags">
    ${pill(row.district)}${pill(statusText,status.kind==='scheduled'?'green':status.kind==='outside'?'orange':'')}
    ${Number.isFinite(distance)?pill(straightDistance(distance)):knownPosition?'':pill('주소로 안내')}
  </div><header class="stack"><h3>${escapeHTML(row.name)}</h3><p class="aed-cabinet"><strong>${escapeHTML(row.place||'건물 안 위치 미확인')}</strong></p><p class="small muted">${escapeHTML(row.address)}</p></header>
  <div class="aed-card-actions actions">${button('보관 위치 복사','aed-copy',{value:row.id,kind:'primary',mark:'clipboard'})}
    ${mapAction(finderLocation.position&&knownPosition?'도보 길찾기':'건물 위치 보기',{name:row.name,position:knownPosition?row:null,query:mapLabel,route:knownPosition&&!!finderLocation.position,kind:'secondary'})}
    ${row.phone?`<a class="btn secondary aed-contact" href="tel:${row.phone}" aria-label="${escapeHTML(row.name)} 기관에 출입 문의">${icon('phone')} 출입 문의</a>`:''}
  </div>
  <p class="small muted">${status.slot?`${AED_DAYS[status.day]} 등록 ${status.slot.label} · `:''}실제 출입·사용 가능 여부 미확인</p>
  <details class="aed-card-source"><summary>요일별 등록 시간과 출처</summary><div class="stack">${aedDaySchedule(row.slots)}
    <p class="small muted">${row.documentUrl?'기관 공개 문서 확인일':'공개 등록 자료 조회일'} · <time datetime="${aedDirectory.checkedOn}">${aedDirectory.checkedOn}</time></p><p class="small">${aedOfficialRecord(row)}</p>
  </div></details></article>`;
}
function aedResults(){
  if(!aedDirectory){
    const state=aedLoadError?'AED 자료를 불러오지 못했어요.':'AED 등록 위치를 불러오는 중이에요.';
    return `<section class="card stack">${coachReadout(`<h2 id="aed-count" role="status">${state}</h2>`)}<div class="actions">
      ${aedLoadError?button('다시 불러오기','aed-retry',{kind:'secondary'}):''}${external('E-Gen에서 AED 찾기',AED_REGISTRY)}
    </div></section>`;
  }
  const results=rankedAedRecords(aedDirectory.records,aedFilters,finderLocation.position,aedLocalClock());
  const shown=results.slice(0,aedFilters.limit),order=finderLocation.position?'직선거리순':'기관명순';
  return `<div class="stack aed-result-list">${coachReadout(`<h2 id="aed-count" role="status">${results.length.toLocaleString('ko-KR')}건 · ${order}</h2>`)}
    ${shown.length?`<div class="stack aed-list">${shown.map(aedCard).join('')}</div>`:
      `<div class="card stack"><p>이 조건에서 확인된 AED가 없어요.</p><div class="actions">${button('검색 조건 초기화','aed-reset',{kind:'secondary'})}${external('E-Gen에서 AED 찾기',AED_REGISTRY)}</div></div>`}
    ${results.length>shown.length?`<div>${button('AED 더 보기','aed-more',{kind:'secondary'})}</div>`:''}
  </div>`;
}
function updateAedResults(announce=false){
  if(view!=='aed-finder')return;
  const target=$('#aed-results');
  if(!target)return;
  target.innerHTML=aedResults();
  if(announce)setLive($('#aed-count').textContent);
}
