const WATER_ACCESS_SOURCES={
  parks:'https://www.data.go.kr/data/15012890/standard.do',suseong:'https://www.suseong.kr/index.do?menu_id=00000147',
  duryu:'https://tour.daegu.go.kr/file/d23e2a2b167e4ce6b10b3f8f31ffefec.pdf#page=181',stores:'https://www.data.go.kr/data/15083033/fileData.do'
};
const WATER_NEED_LISTS={live:'지금 배부 중',fountains:'무료 음수대',stores:'생수 구매처'};
const WATER_NEED_EVIDENCE={
  fountains:{label:'공개 자료에 음수대 등록',status:'가동·음용 가능 여부 미확인',date:'2026-11-24',dateLabel:'등록 자료 확인'},
  stores:{label:'공개 상가자료 등록',status:'현재 영업·재고 미확인',date:'2026-09-30',dateLabel:'상가자료 기준'}
};
const waterNeedLimits={all:6,live:3,fountains:3,stores:3};
let waterNeedDistrict='all',waterNeedKind='all';
let lastWaterNeedLive='';

function resetWaterNeedLimits(){
  for(const id of Object.keys(waterNeedLimits))waterNeedLimits[id]=id==='all'?6:3;
}
function waterNeedPlaces(rows,position=finderLocation.position,district=waterNeedDistrict){
  return rows.filter(row=>district==='all'||row[0]===district).map(([district,name,address,lat,lng,detail])=>({
    district,name,address,lat,lng,detail,distance:position?waterDistance(position,{lat,lng}):null
  })).sort((a,b)=>a.distance-b.distance||a.district.localeCompare(b.district,'ko')||a.name.localeCompare(b.name,'ko'));
}
function waterNeedPlaceCard(row,kind,closest=false){
  const {name,address,district,lat,lng,detail,distance}=row;
  const measure=distance==null?(finderLocation.position?' · 좌표 미등록':''):` · ${straightDistance(distance)}`;
  const evidence=WATER_NEED_EVIDENCE[kind];
  const query=(address.startsWith('대구')?address:`대구 ${address||district}`)+(kind==='stores'?` ${name}`:'');
  const position={lat,lng};
  return `<article class="water-need-place"><div class="stack"><div class="actions">${pill(evidence?.label||'주최자 확인 · 배부 중',kind==='live'?'green':'')}${closest?pill('거리순 첫 장소','green'):''}</div><h3>${escapeHTML(name)}</h3><p class="small muted">${escapeHTML(address||district)}${measure}</p>
    ${evidence?`<div class="stack facility-verification"><p class="small"><strong>${evidence.status}</strong>${kind==='fountains'?' · 지도는 공원 위치 기준':''}</p><p class="small muted">${evidence.dateLabel} · <time datetime="${evidence.date}">${evidence.date}</time></p></div>`:''}
    ${detail?`<p class="small muted">${escapeHTML(detail)}</p>`:''}
  </div><div class="actions water-need-route-actions">${finderRouteButton(name,position)}${mapAction('지도 보기',{name,position,query})}</div></article>`;
}
function waterNeedAlternatives(ranked){
  const action=ranked?'water-need-filter':'water-need-jump';
  return `<div class="actions">${button('무료 음수대 보기',action,{value:'fountains',kind:'secondary'})}${button('생수 구매처 보기',action,{value:'stores',kind:'secondary'})}</div>`;
}
function waterNeedSection(kind,rows,description,empty){
  const title=WATER_NEED_LISTS[kind];
  return `<section id="water-need-${kind}" class="card stack" aria-labelledby="water-need-title-${kind}"><header>${coachReadout(`<h2 id="water-need-title-${kind}">${title}</h2><p class="small muted">${description}</p>`)}</header>${rows.length?`<div class="water-need-places">${rows.slice(0,waterNeedLimits[kind]).map(row=>waterNeedPlaceCard(row,kind)).join('')}</div>`:`<p>${empty}</p>${kind==='live'?waterNeedAlternatives(false):''}`}
    <div class="actions">${rows.length>waterNeedLimits[kind]?button('장소 더 보기','water-need-more',{value:kind}):''}${kind==='live'?button('물 나눔 일정 보기','water-today'):''}${kind==='stores'?mapAction('지도에서 편의점·마트 더 찾기',{name:`대구 ${waterNeedDistrict==='all'?'':`${waterNeedDistrict} `}편의점`}):''}</div></section>`;
}
function waterNeedLiveRows(){
  return waterDirectory({mode:'now',district:waterNeedDistrict}).map(({item,distance})=>({
    ...item,name:item.place,detail:`${item.name} · 주최자 확인 ${waterReportedTime(item.reportedAt)}`,distance
  }));
}
function waterNeedLive(){
  const emptyLive=waterConnection==='loading'?'배부 상황을 확인하고 있어요. 아래 음수대와 구매처는 바로 볼 수 있어요.':waterConnection==='offline'?'최신 배부 상태를 확인할 수 없어요. 아래 음수대와 구매처를 찾아보세요.':'지금 배부 중으로 확인된 행사가 없어요. 아래 음수대와 구매처를 찾아보세요.';
  return waterNeedSection('live',waterNeedLiveRows(),'주최자가 배부 중으로 확인했고, 공지된 운영 시간 안에 있는 곳이에요.',emptyLive);
}
function rankedWaterNeedResults(){
  const sources={live:waterNeedLiveRows,fountains:()=>waterNeedPlaces(WATER_ACCESS_FOUNTAINS),stores:()=>waterNeedPlaces(WATER_ACCESS_STORES)};
  const kinds=waterNeedKind==='all'?Object.keys(sources):[waterNeedKind];
  const rows=kinds.flatMap(kind=>sources[kind]().map(row=>({row,kind})))
    .sort((a,b)=>(a.row.distance??Infinity)-(b.row.distance??Infinity)||Number(b.kind==='live')-Number(a.kind==='live')||a.row.name.localeCompare(b.row.name,'ko'));
  const limit=waterNeedLimits[waterNeedKind];
  const empty=waterNeedKind==='live'&&waterConnection!=='ok'?'배부 상태를 확인 중이거나 최신 정보에 연결할 수 없어요. 무료 음수대나 구매처도 살펴보세요.':'선택한 조건에 맞는 장소가 없어요. 다른 유형이나 구·군을 골라 주세요.';
  const liveSummary=waterNeedKind==='all'&&!rows.some(({kind})=>kind==='live')
    ?(waterConnection==='ok'?'이 조건에서 지금 배부 중으로 확인된 곳은 없어요.':'배부 상태를 확인 중이거나 최신 정보에 연결할 수 없어요.')
    :'';
  return `<section class="card stack" id="water-need-ranked" aria-labelledby="water-need-ranked-title">${coachReadout(`<h2 id="water-need-ranked-title">내 위치에서 가까운 곳</h2><p id="water-need-count" class="small muted" role="status">${rows.length.toLocaleString('ko-KR')}곳 · 직선거리순</p>`)}<p class="small muted">음수대는 공원 위치 기준이에요. 음수대 가동 여부와 점포 영업·재고를 확인하세요.</p>
    ${liveSummary?`<p class="small muted">${liveSummary}</p>`:''}
    ${rows.length?`<div class="water-need-places">${rows.slice(0,limit).map(({row,kind},index)=>waterNeedPlaceCard(row,kind,index===0&&row.distance!=null)).join('')}</div>`:`<p>${empty}</p>${waterNeedKind==='live'?waterNeedAlternatives(true):''}`}
    ${rows.length>limit?`<div>${button('장소 더 보기','water-need-more',{value:waterNeedKind})}</div>`:''}</section>`;
}
function refreshWaterNeedLive(){
  const ranked=!!finderLocation.position;
  if(ranked&&!['all','live'].includes(waterNeedKind))return;
  const next=ranked?rankedWaterNeedResults():waterNeedLive();
  if(next===lastWaterNeedLive)return;
  lastWaterNeedLive=next;
  const selector=ranked?'#water-need-ranked':'#water-need-live';
  const section=$(selector);
  const focused=section?.contains(document.activeElement);
  if(section)section.outerHTML=next;
  if(focused)$(selector+' .btn')?.focus({preventScroll:true});
}
function waterNeedPage(){
  const districts={all:'대구 전체',...Object.fromEntries(DAEGU_DISTRICTS.map(name=>[name,name]))};
  const ranked=!!finderLocation.position;
  lastWaterNeedLive=ranked?rankedWaterNeedResults():waterNeedLive();
  const results=ranked?lastWaterNeedLive:lastWaterNeedLive
    +waterNeedSection('fountains',waterNeedPlaces(WATER_ACCESS_FOUNTAINS),'공개 자료에 음수대가 등록된 공원이에요. 공원 위치가 표시되며, 현장에서 가동 여부와 음용 가능 표시를 확인하세요.','이 구·군에서 공개 자료로 확인한 음수대가 없어요. 다른 구·군을 보거나 가까운 구매처를 확인하세요.')
    +waterNeedSection('stores',waterNeedPlaces(WATER_ACCESS_STORES),'공공 상가자료에 등록된 편의점과 슈퍼마켓이에요. 영업시간과 생수 재고는 매장에서 확인하세요.','이 구·군에서 표시할 구매처가 없어요. 지도에서 주변 편의점이나 마트를 찾아보세요.');
  return `${pageHeading('대구광역시','지금 바로 물이 필요해요')}<div class="stack form-shell water-need-page">
    <p class="small muted">반응이 없거나 호흡이 비정상이면 즉시 <a href="tel:119">119에 전화하세요</a>.</p>
    <section class="card stack" aria-label="물 찾을 지역">${finderControls('water-need-locate','water-need-clear')}<label class="field">찾을 지역<select name="water-need-district">${optionList(districts,waterNeedDistrict)}</select></label></section>
    ${ranked?`<div class="actions water-need-jumps" role="group" aria-label="물 찾기 유형">${Object.entries({all:'전체',...WATER_NEED_LISTS}).map(([id,label])=>`<button type="button" class="btn ${id===waterNeedKind?'primary':'secondary'}" data-action="water-need-filter" data-value="${id}" aria-pressed="${id===waterNeedKind}">${label}</button>`).join('')}</div>`:`<nav class="actions water-need-jumps" aria-label="물 찾기 유형">${Object.entries(WATER_NEED_LISTS).map(([id,label])=>button(label,'water-need-jump',{value:id,kind:'secondary'})).join('')}</nav>`}
    <div id="water-need-results" class="stack">${results}</div>
    <div>${button('지금 운영 시간대인 무더위쉼터','nearby-now',{mark:'snow'})}</div>
    <details><summary>위치 자료 출처</summary><div class="stack"><p>${external('공공데이터포털 · 전국도시공원정보표준데이터',WATER_ACCESS_SOURCES.parks)}<br>${external('수성구청 · 공원현황',WATER_ACCESS_SOURCES.suseong)}<br>${external('대구 관광안내 · 두류공원 편의시설',WATER_ACCESS_SOURCES.duryu)}</p><p>${external('소상공인시장진흥공단 · 상가정보 2026년 9월 30일 기준',WATER_ACCESS_SOURCES.stores)}</p></div></details></div>`;
}
function waterCard({item,status,label,tone,distance=null},{highlight=false,manage=false,shared=false}={}){
  const district=item.district, location=item.address;
  const map=mapAction('지도에서 장소 보기',{name:item.place,position:item,query:`${location} ${item.place}`.trim()});
  const sourceLabel=item.official?'주최 기관 활동 기록':'주최자 공지';
  const formHost=item.signup?new URL(item.signup).hostname:'';
  const distanceLabel=distance!=null?straightDistance(distance):!shared&&!manage&&finderLocation.position&&!validPosition(item)?'좌표 미등록':'';
  return `<article class="card stack water-card${highlight?' water-closest':''}"><div class="actions">${pill(label,tone)}${pill(district)}${pill(item.official?'주최 기관 자료':item.owned?'내 행사':item.live?'주최자 현장 제보':'공유된 주최자 안내')}${highlight?pill('거리순 첫 장소','green'):''}${distanceLabel?pill(distanceLabel):''}</div>
  <h3>${escapeHTML(item.name)}</h3><p class="muted small">${escapeHTML(item.organizer)}</p>
  <div class="water-facts"><div><b>배부 장소</b><p>${escapeHTML(item.place)}<br><span class="muted small">${escapeHTML(location)}</span></p></div><div><b>일정</b><p>${escapeHTML(item.date)}${item.from?` · ${escapeHTML(item.from)}–${escapeHTML(item.to)}`:''}</p></div></div>
  ${item.bottles?`<p class="small muted">${item.official?'기록된 배부량':'주최자 준비 물량'} · ${waterNum.format(item.bottles)}병</p>`:''}
  ${item.note?`<p class="small">${escapeHTML(item.note)}</p>`:''}
  ${item.live&&item.reportedAt?`<p class="small muted">주최자 마지막 현장 갱신 · ${waterReportedTime(item.reportedAt)}</p>`:'<p class="small muted">현장 배부 확인 시각 없음</p>'}
  ${manage&&item.live&&!item.listed?'<p class="small muted">대구 공개 목록에서 숨김</p>':''}
  ${manage&&item.owned&&!item.live?'<p class="small muted">이 기기에 저장된 초안입니다. 공개하면 방문자가 현장 상태를 확인할 수 있습니다.</p>':''}
  <div class="actions">${status!=='past'?`${finderRouteButton(item.place,item)}${map}`:''}${status!=='past'&&item.signup?waterLink(`봉사 신청 (${formHost})`,item.signup,'secondary'):''}${item.source?waterLink(sourceLabel,item.source):''}${shared?button('이 기기에 일정 저장','save-shared-water',{kind:'secondary'}):''}${manage&&item.owned?button('일정·장소 수정','water-edit',{value:item.id,mark:'edit'}):''}${manage&&item.owned?button(item.live?'현장 상태판':'행사 공개','water-manage',{value:item.id,kind:'primary'}):''}${!shared&&!item.official?button('행사·모집 링크','water-share',{value:item.id,mark:'pin'}):''}${item.live&&item.listed&&!manage?button('잘못된 정보 신고','water-flag',{value:item.id}):''}${manage&&!(item.owned&&item.live)?button('목록에서 삭제','water-remove',{value:item.id}):''}</div>${shared?`<div class="actions">${button('배부 중인 다른 행사 찾기','water-now',{kind:'secondary',mark:'pin'})}${button('가까운 배부 장소 찾기','water-live-near',{mark:'pin'})}</div>`:''}</article>`;
}
function waterResults(){
  const results=waterDirectory(), first=results.find(result=>result.distance!==null);
  const ranked=!!(finderLocation.position&&waterMode!=='past');
  const closest=ranked?first:null;
  const empty={today:'오늘 등록된 행사가 없습니다.',now:'현재 배부 중으로 확인된 행사가 없습니다.',future:'확인할 수 있는 예정 일정이 없습니다.',past:'이 조건에 해당하는 지난 일정이 없습니다.',mine:'이 기기에 만든 행사나 저장한 공유 일정이 없습니다.'};
  const copy=results.length?`${results.length}건${ranked?' · 좌표가 있는 행사를 직선거리순으로 표시':''}`:empty[waterMode];
  const connectionText=waterConnection==='loading'?'공개 현장 상태를 불러오는 중입니다.':'현장 상태에 연결하지 못했습니다. 최신 배부 여부는 확인이 필요합니다.';
  return `${waterConnection==='ok'?'':`<p class="small muted" role="status">${connectionText}</p>`}${coachReadout(`<p id="water-result-count" class="shelter-count" role="status">${copy}</p>`)}${ranked&&results.length&&!closest?notice('목록에 좌표가 있는 행사가 없습니다. 주소로 지도에서 위치를 확인하세요.','warn'):''}${results.length?`<div class="water-grid">${results.map(row=>waterCard(row,{highlight:row===closest,manage:waterMode==='mine'})).join('')}</div>`:''}${(!results.length&&['now','today','future'].includes(waterMode))?`<div class="card actions">${waterMode==='now'?button('오늘 전체 일정 보기','water-today'):''}${button('대구 무더위쉼터 찾기','nearby',{kind:'secondary',mark:'pin'})}${waterLink('대구자원봉사센터 공지', 'https://dgvolunteer.co.kr/')}</div>`:''}`;
}
