function districtHeatProfiles(){
  const districtRows=WATER_DISTRICT_PROFILES.map(row=>{
    const {housing:[homes,olderHomes,detached],land:[area,forest,urban,farm],jobs:[jobs,...sectorTotals]}=DISTRICT_HEAT_CONTEXT[row.district];
    return {...row,homes,olderHomes,olderHomesShare:olderHomes/homes,detachedShare:detached/homes,area,density:row.population/(area/1e6),forestShare:forest/area,urbanShare:urban/area,farmShare:farm/area,
      industries:Object.keys(DISTRICT_HEAT_SECTORS).map((id,index)=>({id,count:sectorTotals[index],share:sectorTotals[index]/jobs}))};
  });
  const median=values=>{
    const ordered=[...values].sort((a,b)=>a-b);
    const middle=Math.floor(ordered.length/2);
    return (ordered[middle]+ordered[Math.ceil(ordered.length/2)-1])/2;
  };
  const baseline=Object.fromEntries(['heat','olderShare','older','olderHomesShare','olderHomes','detachedShare','density','urbanShare','farmShare','shelterRate'].map(metric=>[metric,median(districtRows.map(row=>row[metric]))]));
  const sectorMedian=Object.keys(DISTRICT_HEAT_SECTORS).map((_,i)=>median(districtRows.map(row=>row.industries[i].share)));
  const eveningReference=Date.parse('2026-07-15T18:00:00+09:00');
  const eveningCounts=waterCountByDistrict(WATER_PUBLIC_SHELTERS.filter(row=>matchesShelterHours(row[5],{time:'now'},eveningReference)));
  return {baseline,rows:new Map(districtRows.map(row=>[row.district,{...row,evening:eveningCounts[row.district],industries:row.industries
    .map((industry,i)=>({...industry,relative:industry.share/sectorMedian[i]})).sort((a,b)=>b.relative-a.relative)}]))};
}
let districtHeatSelection='중구';
let districtHeatData;
const districtPct=value=>(value*100).toFixed(1)+'%';
const districtNum=value=>waterNum.format(value);
function districtHeatPriorities(row,baseline){
  const {older,olderShare,density,urbanShare,farmShare,olderHomes,olderHomesShare,detachedShare,evening,shelterRate}=row;
  const industry=row.industries[0];
  const sector=DISTRICT_HEAT_SECTORS[industry.id];
  const spread=density<baseline.density/3;
  const lowShelter=shelterRate<baseline.shelterRate;
  const measures=[
    {key:'older',weight:Math.max(older/baseline.older,olderShare/baseline.olderShare),target:'65세 이상 주민',
      title:spread?'마을 단위 방문 점검과 쉼터 이동 지원':'동별 복지망으로 냉방 점검과 평상시 연결',
      action:spread?'읍·면별로 방문·전화 점검 구역을 맡기고 정류장과 마을회관을 중심으로 쉼터에 이동할 방법을 확인하세요.':'동별 방문복지팀과 함께 냉방과 이동 지원이 필요한 주민을 사전에 확인하고, 더운 날 연락할 기관과 개방 시간대를 공유하세요.',
      reason:'65세 이상 주민 '+districtNum(older)+'명('+districtPct(olderShare)+') · 인구밀도 ㎢당 '+districtNum(Math.round(density))+'명'},
    {key:'housing',weight:Math.max(olderHomesShare/baseline.olderHomesShare,olderHomes/baseline.olderHomes),target:'2000년 이전에 지은 주택 중 실내 냉방이 취약한 가구',
      title:detachedShare>baseline.detachedShare?'노후 단독주택을 찾아 실내 냉방 보강':'오래된 공동주택의 공용 냉방 공간과 실내 환경 점검',
      action:detachedShare>baseline.detachedShare?'동별 방문조사로 냉방기 접근과 실내온도를 확인하고, 취약 가구부터 차양·환기와 냉방 지원을 연결하세요.':'관리사무소 또는 주민대표와 최상층·서향 가구의 실내 환경을 점검하고, 건물 공용 냉방공간의 개방 시간과 이용 대상도 확인하세요.',
      reason:'2000년 이전 주택 '+districtNum(olderHomes)+'호('+districtPct(olderHomesShare)+') · 전체 단독주택 '+districtPct(detachedShare)},
    {key:'industry',weight:Math.min(2.25,industry.relative),target:sector.target,title:sector.title,action:sector.action,
      reason:sector.label+' 종사자 '+districtNum(industry.count)+'명 · 조사에서 집계한 해당 구·군 종사자의 '+districtPct(industry.share)},
    {key:'land',weight:urbanShare>baseline.urbanShare?Math.min(2.3,urbanShare/baseline.urbanShare):farmShare>baseline.farmShare?Math.min(1.6,1+(farmShare-baseline.farmShare)*4):0,
      target:urbanShare>baseline.urbanShare?'대중교통 대기자와 그늘이 적은 길의 보행자':'밭·논·과수원에서 일하는 사람',
      title:urbanShare>baseline.urbanShare?'정류장과 보행 연결로의 그늘부터 확인':'농작업 구역 가까이에 쉴 곳과 식수 마련',
      action:urbanShare>baseline.urbanShare?'주민센터와 대중교통 정류장을 잇는 길에서 오후 그늘을 직접 조사하고, 대기 지점부터 그늘막·가로수·쉼터 안내를 보강하세요.':'마을·농업단체와 함께 밭·논·과수원 인근의 그늘과 식수 보급 위치를 확인하고, 더운 시간대 작업 조정 안내를 전달하세요.',
      reason:urbanShare>baseline.urbanShare?'대지·공장용지·도로 '+districtPct(urbanShare)+' · 대구 9개 구·군 중앙값 '+districtPct(baseline.urbanShare):'밭·논·과수원 등록 면적 비중 '+districtPct(farmShare)},
    {key:'shelter',weight:evening===0?2.5:lowShelter?Math.min(2.4,0.75+baseline.shelterRate/shelterRate/2):0,
      target:'저녁 시간대 냉방 장소가 필요한 주민',
      title:evening===0?'저녁에 개방하는 대체 냉방 공간 확보':'등록 쉼터가 적은 생활권에 분산 배치',
      action:'공개 등록 쉼터가 부족한 동을 확인하고, 도서관·복지시설 등 공공 실내공간의 이용 가능 시간, 냉방, 문턱과 화장실을 검증해 대체 장소를 안내하세요.',
      reason:'고령인구 1만 명당 공개 일반 운영표 쉼터 '+shelterRate.toFixed(1)+'곳 · 예시 평일 18시 운영표 '+evening+'곳'}
  ];
  return measures.sort((a,b)=>b.weight-a.weight).slice(0,3);
}
function communityHeatResult(){
  const {baseline,rows}=districtHeatData;
  const row=rows.get(districtHeatSelection);
  const {district,heat,older,olderShare,olderHomesShare,detachedShare,density,forestShare,urbanShare,farmShare,shelters,shelterRate,evening,fountains}=row;
  const priorities=districtHeatPriorities(row,baseline);
  const sector=row.industries[0], sectorLabel=DISTRICT_HEAT_SECTORS[sector.id].label;
  const [lower,middle,upper]=DISTRICT_ELEVATION[district];
  const terrainNote=upper-lower>=250?'구·군 안에서도 높낮이 차가 커요. 저지대 주거·작업 구역을 나눠 현장 온도와 그늘을 조사하세요.':'고도 자료와 함께 생활권의 가로 그늘, 포장과 바람길을 현장에서 확인하세요.';
  const difference=(heat-baseline.heat).toFixed(1);
  const exposure=Number(difference)===0?'9개 구·군 중앙값과 같아요.':'9개 구·군 중앙값보다 '+Math.abs(Number(difference)).toFixed(1)+'일 '+(difference>0?'많아요.':'적어요.');
  const heatSource=district==='군위군'?WATER_PLANNING_SOURCES.gunwiHeat:WATER_PLANNING_SOURCES.heat;
  const measures=[
    ['기상 노출',heat.toFixed(1)+'일', '연평균 폭염일. '+exposure+' 기준 기간 2000–2019년.',external('기상청 전망보고서 · 표 3-5',heatSource)],
    ['지형·토지 이용','지표 고도 중앙값 약 '+middle+'m','10백분위 약 '+lower+'m · 90백분위 약 '+upper+'m. 임야 '+districtPct(forestShare)+' · 대지·공장용지·도로 '+districtPct(urbanShare)+' · 밭·논·과수원 '+districtPct(farmShare)+'. '+terrainNote,external(...DISTRICT_HEAT_SOURCES.terrain)+' · '+external(...DISTRICT_HEAT_SOURCES.land)],
    ['인구','65세 이상 '+districtPct(olderShare),districtNum(older)+'명 · 2026년 6월 주민등록. 비율과 실제 지원 대상 규모를 함께 비교해요.',external('대구정책연구원 · 2026년 6월 인구',WATER_PLANNING_SOURCES.population)],
    ['주거환경','2000년 이전 건축 '+districtPct(olderHomesShare),'단독주택 '+districtPct(detachedShare)+' · 2024년 주택총조사. 실제 실내온도와 냉방기 보유 여부는 확인이 필요해요.',external(...DISTRICT_HEAT_SOURCES.housing)],
    ['산업환경',sectorLabel+' '+districtPct(sector.share),'비교한 업종 중 대구 9개 구·군 중앙값 대비 집중도가 가장 높아요. 업종별 종사자 수로 작업 장소나 피해 규모를 확인할 수 없어요.',external(...DISTRICT_HEAT_SOURCES.jobs)],
    ['쉼터·식수 인프라','공개 일반 쉼터 '+shelters+'곳','고령인구 1만 명당 '+shelterRate.toFixed(1)+'곳(중앙값 '+baseline.shelterRate.toFixed(1)+'곳) · 예시 평일 18시 '+evening+'곳 · '+(fountains===null?'음수대 공개 목록 미확인':'음수대 등록 공원 '+fountains+'곳')+'.',sourceLink('map')]
  ];
  const gap=evening===0?'예시 평일 18시 등록 운영표에서 일반 개방 쉼터가 확인되지 않았어요. 저녁에 이용할 대체 공공 실내시설을 먼저 확인할 수 있어요.'
    :shelterRate<baseline.shelterRate?'고령인구 대비 공개 쉼터 수가 9개 구·군 중앙값보다 적어요. 거주지에서 멀거나 이용 시간이 짧은 생활권이 있는지 먼저 확인하세요.'
    :density<baseline.density/3?'인구가 넓게 분포하는 지역이에요. 쉼터 수와 함께 마을별 이동 거리와 교통 수단을 확인하세요.':'등록 수와 함께 저녁 이용시간, 도보 접근, 무장애 출입, 냉방 여부를 점검하세요.';
  const waterGap=fountains===null?'무료 음수대 통합 목록을 확인하지 못했어요. 공동 식수 제공 장소와 현장 가동 여부를 먼저 조사하세요.'
    :row.fountainRate<WATER_FOUNTAIN_MEDIAN?'공개 자료를 확보한 구·군 가운데 고령인구 대비 음수대 등록 공원 수가 중앙값보다 적어요.':'공개 목록의 음수대가 언제 가동되는지와 식수 수요가 큰 생활권을 확인하세요.';
  return `<section class="card stack community-summary" aria-labelledby="community-result-title">
    ${coachReadout(`<h2 id="community-result-title" tabindex="-1">${district} 폭염 예방 우선과제</h2><p class="muted">연평균 폭염일수는 ${heat.toFixed(1)}일이에요. ${exposure}</p>`)}
    <ol class="community-priorities">${priorities.map(({title,target,action,reason})=>`<li><h3>${title}</h3><p class="community-target"><strong>주요 보호 대상</strong> ${target}</p><p>${action}</p><p class="muted small"><b>추천 근거</b> ${reason}</p></li>`).join('')}</ol>
  </section>
  <section class="card stack"><h2>지역 대응 인프라 점검</h2><p>${gap}</p><p>${waterGap}</p>
    <div class="community-service-actions">
      ${button(district+' 쉼터·대체시설 찾기','community-shelters',{value:district,kind:'secondary',mark:'pin'})}
      ${button(district+' 물 나눔 후보 추천','water-plan-start',{value:district,kind:'secondary',mark:'drop'})}
      ${button('식수 지원 지도에서 비교','community-water-map',{value:district,kind:'secondary',mark:'chart'})}
    </div>
  </section>
  <section class="card stack"><h2>수치와 공식 자료</h2>
    <div class="community-evidence">${measures.map(([label,value,copy,link])=>`<article><h3>${label}</h3><p><strong>${value}</strong></p><p class="small muted">${copy}</p><p class="small">${link}</p></article>`).join('')}</div>
  </section>`;
}

const COMMUNITY_WEATHER_API=new URL('/api/district-weather',WATER_API).href;

const DISTRICT_WEATHER_POINTS={
  '중구':['동인동',35.8718,128.6076],'동구':['신암4동',35.8838,128.6271],
  '서구':['평리3동',35.8778,128.5589],'남구':['대명5동',35.8448,128.5875],
  '북구':['침산3동',35.8934,128.5903],'수성구':['범어1동',35.8520,128.6284],
  '달서구':['월성1동',35.8265,128.5300],'달성군':['논공읍',35.7511,128.4427],
  '군위군':['군위읍',36.2335,128.5688]
};
async function secondaryDistrictForecast(district,signal){
  const [area,latitude,longitude]=DISTRICT_WEATHER_POINTS[district];
  const url=new URL('https://api.open-meteo.com/v1/forecast');
  url.search=new URLSearchParams({latitude,longitude,hourly:'temperature_2m,relative_humidity_2m',
    models:'ecmwf_ifs025',forecast_hours:7,past_hours:1,timeformat:'unixtime',timezone:'Asia/Seoul'}).toString();
  const response=await fetch(url,{signal,credentials:'omit'});
  if(!response.ok)throw Error('Forecast unavailable');
  const {hourly}=await response.json(),now=Date.now();
  const slots=(hourly?.time||[]).flatMap((seconds,index)=>{
    const at=seconds*1000,temperature=hourly.temperature_2m?.[index],humidity=hourly.relative_humidity_2m?.[index];
    return Number.isFinite(at)&&at>=now-3600000&&at<=now+6*3600000&&Number.isFinite(temperature)&&temperature>=-50&&temperature<=60
      ?[{at,temperature,humidity:Number.isFinite(humidity)?humidity:null}]:[];
  });
  if(!slots.length)throw Error('Forecast empty');
  return {district,observation:null,forecast:{area,source:'ecmwf',issued:null,slots},alerts:null,urls:{
    forecast:'https://www.ecmwf.int/en/forecasts/datasets/open-data',
    delivery:'https://open-meteo.com/en/docs/ecmwf-api'
  }};
}
async function districtWeatherSnapshot(district,signal){
  const primary=new AbortController();
  const forward=()=>primary.abort();
  signal.addEventListener('abort',forward,{once:true});
  const timer=setTimeout(forward,4300);
  try{
    const response=await fetch(COMMUNITY_WEATHER_API+'?district='+encodeURIComponent(district),{signal:primary.signal});
    const snapshot=await response.json();
    if(response.ok&&snapshot.district===district&&(snapshot.observation||snapshot.forecast))return snapshot;
  }catch{
    // A missing regional response is handled by the independently sourced forecast.
  }finally{
    clearTimeout(timer);
    signal.removeEventListener('abort',forward);
  }
  if(signal.aborted)throw Error('Weather request ended');
  return secondaryDistrictForecast(district,signal);
}

const communityWeather={mode:'live',cache:new Map(),manual:null,controller:null,district:'',status:'',timer:0};
const HEAT_PLANNING_BANDS=['평상시 준비','더위 대비 강화','폭염 대비 강화','고온 대응 집중'];
const heatClock=stamp=>new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(stamp);
const heatHour=stamp=>new Date(stamp+9*3600000).getUTCHours();
const heatC=value=>Number.isFinite(value)?value.toFixed(1).replace(/\.0$/,'')+'℃':'확인 불가';
function weatherSnapshot(){
  const stored=communityWeather.cache.get(districtHeatSelection);
  return stored&&Date.now()-stored.checked<10*60000?stored:null;
}
function relevantHeatAlerts(alerts,district){
  if(!alerts)return [];
  return alerts.districts.filter(({name})=>{
    if(/군위.*제외/.test(name))return district!=='군위군';
    if(name.includes(district))return true;
    return district!=='군위군' && /^(?:대구광역시|대구)$/.test(name);
  });
}
function districtHeatSituation(){
  const now=Date.now();
  if(communityWeather.mode==='manual'){
    const manual=communityWeather.manual;
    return manual?{main:{kind:'manual',temperature:manual.temperature},at:manual.at,alert:null,next:[],snapshot:null}:null;
  }
  const snapshot=weatherSnapshot();
  const observation=snapshot?.observation;
  const next=snapshot?.forecast?.slots.filter(slot=>slot.at>=now-3600000&&slot.at<=now+4*3600000)||[];
  const currentForecast=next.find(slot=>slot.at>=now)||next.at(-1);
  const current=observation&&now-observation.at<=35*60000?{...observation,kind:'observation'}
    :currentForecast?{...currentForecast,kind:'forecast'}:null;
  const matched=relevantHeatAlerts(snapshot?.alerts,districtHeatSelection);
  if(!current&&!matched.length)return null;
  return {main:current,at:current?.at||now,alert:matched,next:next.filter(slot=>slot.at>=now).slice(0,3),snapshot};
}
function districtTrainingPlaces(district,situation=null){
  const data=districtHeatData??=districtHeatProfiles(),row=data.rows.get(district);
  if(!row)return [];
  const first=situation?weatherPriorities(situation,row).measures:districtHeatPriorities(row,data.baseline);
  const places=first.flatMap(item=>{
    if(item.key==='industry')return RANDOM_PLACES[row.industries[0].id]||[];
    if(item.key==='land')return RANDOM_PLACES[row.urbanShare>data.baseline.urbanShare?'shade':'farm'];
    return RANDOM_PLACES[item.key]||[];
  });
  return [...new Set(places)];
}
function openDistrictRandomDrill(){
  const district=districtHeatSelection;
  const situation=districtHeatSituation(),main=situation?.main;
  openRandomDrill({district,places:districtTrainingPlaces(district,situation),weather:main?{kind:main.kind,temperature:main.temperature}:null});
}
function communitySheltersAt(district,at){
  return WATER_PUBLIC_SHELTERS.filter(row=>row[0]===district&&matchesShelterHours(row[5],{time:'now'},at)).length;
}
function weatherPriorities(situation,row){
  const {main,at,alert,next}=situation;
  const temp=main&&Math.max(main.temperature,main.feelsLike??main.temperature);
  const forecastPeak=next.reduce((peak,item)=>Math.max(peak,item.temperature),-Infinity);
  const band=value=>value>=35?3:value>=33?2:value>=30?1:0;
  const alertLevel=alert?.some(item=>item.code==='hw4'||item.code==='hw3')?3:alert?.some(item=>item.code==='hw2')?2:0;
  const level=Math.max(band(temp),band(forecastPeak),alertLevel);
  const shelters=communitySheltersAt(row.district,at);
  const late=heatHour(at)>=18||heatHour(at)<8||alert?.some(item=>item.code==='hwk');
  const local=districtHeatPriorities(row,districtHeatData.baseline);
  const publicSpace={
    key:'shelter',title:shelters?'열려 있는 쉼터의 개방 여부와 이동 지원 확인':'대체 냉방 공간과 이동 수단 확보',
    target:'냉방이나 이동 지원이 필요한 주민',
    action:shelters?'등록 운영표에 나온 시설의 개방·냉방·접근성을 확인하고 동별 안내망에 전달하세요.':'도서관 등 공공 실내시설의 이용 가능 여부를 확인하고 전화 안내나 이동 지원을 연결하세요.',
    reason:'해당 시각 공개 일반 운영표에서 확인한 쉼터 '+shelters+'곳'
  };
  const evening={
    key:'older',title:'해가 진 뒤 실내 열 노출과 연락 체계 확인',target:'노후주택과 이동·냉방 지원 필요 가구',
    action:'생활지원 인력과 협의해 실내 냉방이 취약한 가구의 연락·방문 순서를 정하고 저녁에 쓸 시설을 확인하세요.',
    reason:'65세 이상 '+districtPct(row.olderShare)+' · 2000년 이전 건축 주택 '+districtPct(row.olderHomesShare)
  };
  const measures=level===0
    ? [{...local[0],title:'더운 시간대에 대비해 우선 점검',action:local[0].action}]
    :late?[evening,publicSpace,...local.filter(item=>item.key!=='shelter')]:[...local.filter(item=>item.key!=='shelter').slice(0,2),publicSpace];
  return {level,shelters,measures:measures.slice(0,3)};
}
function communityWeatherResult(){
  const {mode,status}=communityWeather;
  const situation=districtHeatSituation(),snapshot=mode==='live'?weatherSnapshot():null;
  if(!situation)return `<p id="community-weather-status" role="status" class="small muted">${mode==='manual'?'기온과 확인할 시각을 입력해 보세요.':status==='loading'?'기상청 관측·예보를 불러오는 중이에요.':'현재 사용할 기상 자료를 확인하지 못했어요. 다시 조회하거나 기온을 직접 입력해 보세요.'}</p>`;
  const {main,at,alert,next}=situation;
  const row=districtHeatData.rows.get(districtHeatSelection);
  const {level,shelters,measures}=weatherPriorities(situation,row);
  const secondary=snapshot?.forecast?.source==='ecmwf';
  const condition=mode==='manual'?'가정한 기온 · '+heatClock(at)
    :main?.kind==='observation'?main.area+' · '+main.station+' 관측소 · '+heatClock(main.at)
    :main?.kind==='forecast'?row.district+' '+snapshot.forecast.area+' · '+heatClock(main.at)+' 예보'+(secondary?' · ECMWF':''):'기상청 폭염특보 기준';
  const forecastText=next.length?'단기예보 '+next.map(slot=>heatClock(slot.at).split(' ').at(-1)+' '+heatC(slot.temperature)).join(' · '):'';
  const codes={hw2:'폭염주의보',hw3:'폭염경보',hw4:'폭염중대경보',hwk:'열대야주의보'};
  const alerts=alert?.length?alert.map(item=>codes[item.code]+' · '+item.name).join(' / ')
    :snapshot?.alerts?.empty?'기상청 발효 목록에서 확인된 폭염·열대야 특보 없음'
    :mode==='manual'?'기온만 가정해 대응 순서를 비교해요.':'특보 구역은 기상청 현황에서 확인하세요.';
  return `<div class="stack weather-outcome" id="community-weather-status" aria-live="polite">
    <div class="weather-facts"><p class="weather-temp">${main?heatC(main.temperature):'관측 미확인'}</p><div><strong>${escapeHTML(condition)}</strong>
      <p class="small muted">${main?.kind==='forecast'?(secondary?'기상청 연결 지연 · ECMWF 대표 지점 예보':'해당 구·군 관측값 확인 불가 · 예보 시각 기준'):main?.kind==='observation'?['체감 '+heatC(main.feelsLike), main.humidity===null?'':'습도 '+main.humidity+'%'].filter(Boolean).join(' · '):''}</p></div></div>
    ${forecastText?`<p class="small muted">${forecastText}${snapshot.forecast.issued?' · 발표 '+heatClock(snapshot.forecast.issued):''}</p>`:''}
    <div class="actions">${pill(HEAT_PLANNING_BANDS[level],level>=2?'orange':'green')}<span class="small muted">${escapeHTML(alerts)}</span></div>
    <ol class="community-priorities">${measures.map(({title,target,action,reason})=>`<li><h3>${title}</h3><p class="community-target"><strong>우선 보호</strong> ${target}</p><p>${action}</p><p class="small muted"><strong>근거</strong> ${reason}</p></li>`).join('')}</ol>
    <p class="small muted">${heatClock(at)} 기준 공개 일반 운영표 쉼터 ${shelters}곳. 현장 개방·정원은 별도 확인이 필요해요.</p>
    <div class="actions">${button('이 조건으로 랜덤 훈련','community-random-drill',{kind:'primary',mark:'play'})}
      ${button('지금 쉼터·대체시설 찾기','community-shelters',{value:row.district,kind:'secondary',mark:'pin'})}</div>
    <div class="shelter-links">${snapshot?.urls?.observation&&main?.kind==='observation'?external('기상청 관측 원자료',snapshot.urls.observation):''}${snapshot?.urls?.forecast?external(secondary?'ECMWF 공개 예보 원자료':'기상청 동네예보',snapshot.urls.forecast):''}${secondary?external('Open-Meteo 시간별 변환',snapshot.urls.delivery)+external('CC BY 4.0','https://creativecommons.org/licenses/by/4.0/'):''}${external('폭염·열대야 특보',WATER_PLANNING_SOURCES.heatNotice)}</div>
  </div>`;
}
