let waterPlanOptions=[];
let waterPlanner={open:false,team:'',availableFrom:'',availableTo:'',result:''};
const waterMinutes=time=>Number(time.slice(0,2))*60+Number(time.slice(3));
function waterWindowOverlaps(event,from,to){
  return waterMinutes(event.from)<to&&waterMinutes(event.to)>from;
}
function planningVenueForTime(district,venues,day,from,to){
  return venues.find(row=>{
    if(row[0]!==district)return false;
    const [opens,closes,days]=row[5];
    if(closes<opens)return !!((days&(1<<day))&&from>=opens||(days&(1<<((day+6)%7)))&&to<=closes);
    return !!(days&(1<<day))&&from>=opens&&to<=closes;
  });
}
function recommendWaterPlans(input,snapshot,now=Date.now()){
  const {date,bottles,team,availableFrom,availableTo}=input;
  const dateStart=Date.parse(date+'T00:00:00+09:00');
  const currentDate=waterDate(now);
  const day=(new Date(dateStart+9*3600000).getUTCDay()+6)%7;
  const latest=waterMinutes(availableTo), earliest=waterMinutes(availableFrom);
  const start=date===currentDate?Math.max(earliest,Math.ceil((now-dateStart)/900000)*15):earliest;
  const duration=Math.min(latest-start,60);
  if(duration<15)return [];
  const planned=plannedWaterEvents(snapshot).filter(event=>event.id!==input.editId);
  const cityActive=planned.filter(event=>waterWindowOverlaps(event,earliest,latest));
  const sites=WATER_PUBLIC_SHELTERS.filter(row=>row[9]&&/행정복지센터|주민센터|동사무소|복지관|도서관|주민자치|면사무소|읍사무소|보훈회관|문화센터|문화회관|구민회관|복합커뮤니티/.test(row[1]+' '+row[2]));
  const times=[...new Set([start,...Array.from({length:Math.floor((latest-duration-start)/15)+1},(_,index)=>start+index*15),latest-duration])];
  const compare=(a,b)=>a.hot-b.hot||a.overlap-b.overlap||a.daily.length-b.daily.length||b.priority-a.priority||a.cityOverlap-b.cityOverlap||a.from-b.from;
  const optionsByDistrict=WATER_DISTRICT_PROFILES.flatMap(row=>{
    const daily=planned.filter(event=>event.district===row.district);
    const options=times.flatMap(from=>{
      const to=from+duration;
      const venue=planningVenueForTime(row.district,sites,day,from,to);
      if(!venue)return [];
      const matching=daily.filter(event=>waterWindowOverlaps(event,from,to));
      const overlap=matching.length, cityOverlap=planned.filter(event=>waterWindowOverlaps(event,from,to)).length;
      const priority=row.risk+(row.fountainRate!==null&&row.fountainRate<WATER_FOUNTAIN_MEDIAN ? .15 : 0);
      const hot=from<1020&&to>840;
      return [{row,venue,date,from,to,hot,priority,overlap,cityOverlap,daily,bottles,team,cityActive,
        known:matching.reduce((total,event)=>total+(event.bottles||0),0),
        unknown:matching.filter(event=>!event.bottles).length}];
    }).sort(compare);
    return options.slice(0,1);
  }).sort(compare);
  const selected=optionsByDistrict.find(option=>option.row.district===input.preferredDistrict);
  return selected?[selected,...optionsByDistrict.filter(option=>option!==selected).slice(0,2)]:optionsByDistrict.slice(0,3);
}
