// A small supervised classifier trained on the labeled example sentences above.
// Character grams support Korean inflections and spaces without a dictionary.
function fieldGrams(text){
  const normalized=text.toLowerCase().replace(/[^가-힣a-z0-9]/g,'').replace(/\d+/g,'0');
  const features=new Set();
  for(const n of [2,3])for(let i=0;i+n<=normalized.length;i++)features.add(normalized.slice(i,i+n));
  return features;
}
function trainFieldClassifier(corpus){
  const columns=Object.entries(corpus).map(([label,examples])=>{
    const counts=new Map();
    for(const example of examples)for(const token of fieldGrams(example))counts.set(token,(counts.get(token)||0)+1);
    return {label,counts,total:[...counts.values()].reduce((sum,count)=>sum+count,0)};
  });
  const vocabulary=new Set(columns.flatMap(column=>[...column.counts.keys()]));
  return {columns,vocabulary};
}
const fieldClassifier=trainFieldClassifier(FIELD_SAMPLES);
function rankFieldSentence(sentence,model=fieldClassifier){
  const tokens=[...fieldGrams(sentence)].filter(token=>model.vocabulary.has(token));
  if(tokens.length<5)return null;
  const scores=model.columns.map(({label,counts,total})=>{
    const score=tokens.reduce((sum,token)=>sum+Math.log(((counts.get(token)||0)+0.65)/(total+0.65*model.vocabulary.size)),0);
    return {label,score,matches:tokens.filter(token=>counts.has(token)).length};
  }).sort((a,b)=>b.score-a.score);
  const [best,second]=scores;
  return best.label!=='other'&&best.matches>=3&&best.score-second.score>=0.9?best.label:null;
}
