const LIVE_OTHER_SUPPORT={solo:'나 혼자',two:'2명',three:'3명',many:'4명 이상'};
const LIVE_SELF_SUPPORT={solo:'혼자 있어요',with:'도와줄 사람이 있어요'};
const LIVE_NUMBER_WORDS={한:1,두:2,세:3,네:4,다섯:5,여섯:6,일곱:7,여덟:8,아홉:9,열:10};
const LIVE_RESPONDER_NUMBER=String.raw`(\d{1,3}|${Object.keys(LIVE_NUMBER_WORDS).join('|')})\s*(?:명|분)(\s*이상)?`;
const LIVE_TEAM_COUNT_PATTERNS=[
  ['team',String.raw`(?:저|나)(?:를)?\s*포함(?:해서|해)?\s*(?:총\s*)?${LIVE_RESPONDER_NUMBER}`],
  ['helpers',String.raw`(?:저|나)(?:를)?\s*(?:빼고|말고|외에)\s*${LIVE_RESPONDER_NUMBER}`],
  ['helpers',String.raw`(?:저를|나를|저한테|나한테)\s*(?:도와줄|도울)\s*(?:사람|분)(?:은|는|이|가)?\s*${LIVE_RESPONDER_NUMBER}`],
  ['team',String.raw`(?:대응(?:\s*가능한?)?\s*(?:인원|인력)|구조\s*인원|(?:(?:도울|도와줄)\s*(?:수\s*있는\s*)?|대응\s*할\s*수\s*있는\s*)(?:사람|분|인원))(?:은|는|이|가|도)?\s*(?:총\s*)?${LIVE_RESPONDER_NUMBER}`],
  ['team',String.raw`${LIVE_RESPONDER_NUMBER}(?:이|가|은|는)?\s*(?:지금\s*|함께\s*)?(?:도울\s*수\s*있|도와줄\s*수\s*있|대응(?:할\s*수\s*있|하고\s*있)|돕고\s*있)`]
].map(([kind,pattern])=>[kind,new RegExp(pattern,'g')]);
const LIVE_ALONE=/혼자(?:서)?\s*(?:대응(?:\s*중|하고\s*있)|돕고\s*있|도울\s*수\s*있)|(?:저|나)\s*혼자(?:예요|에요|입니다)|(?:도와줄|도울)\s*(?:사람|분)(?:이|은)?\s*없(?:어요|습니다|고)/g;
const LIVE_SELF_ALONE=/(?:(?:저는|제가|나는|내가|저|나)\s*)?혼자(?:예요|입니다|\s*있(?:어요|습니다|고))/g;
const LIVE_HELP_PRESENT=/(?:옆에\s*)?(?:도와줄|도울)\s*(?:사람|분)(?:이|은)?\s*있(?:어요|습니다|고)/g;
let liveSupportSelection={self:null,other:null};

function readLiveSupport(value){
  let situation=value;
  const matches=[];
  for(const [kind,pattern] of LIVE_TEAM_COUNT_PATTERNS){
    situation=situation.replace(pattern,(full,number,minimum,offset)=>{
      // Ranges, changes and uncertain figures stay for the user to select.
      const rest=situation.slice(offset+full.length);
      if(/^\s*(?:(?:이|가|은|는)?\s*아니|(?:에서|보다|미만|뒤에|후에)|[~–-]|\d|(?:일\s*수|인\s*것\s*같|같|될\s*예정))/.test(rest))return full;
      const count=LIVE_NUMBER_WORDS[number]||Number(number);
      if(minimum&&count<4)return ' ';
      if(count>0)matches.push({kind,count});
      return ' ';
    });
  }
  situation=situation.replace(LIVE_ALONE,()=>{matches.push({kind:'alone',count:1});return ' ';});
  const selfAlone=inferLiveSubject(situation)==='self'||/^\s*혼자\s*있/.test(situation);
  if(selfAlone)situation=situation.replace(LIVE_SELF_ALONE,()=>{matches.push({kind:'selfAlone',count:1});return ' ';});
  situation=situation.replace(LIVE_HELP_PRESENT,()=>{matches.push({kind:'present',count:1});return ' ';});
  const signatures=new Set(matches.map(({kind,count})=>kind+' '+count));
  return {situation:situation.trim(),support:signatures.size===1?matches[0]:null};
}

function choiceFromLiveSupport(support,subject){
  if(!support)return '';
  const {kind,count}=support;
  if(kind==='alone'||kind==='selfAlone')return 'solo';
  if(subject==='self')return kind==='team'&&count===1?'solo':'with';
  if(kind==='present')return '';
  const total=kind==='helpers'?count+1:count;
  return total===1?'solo':total===2?'two':total===3?'three':'many';
}

