document.addEventListener('click',event=>{
  if(event.target.id==='water-district-canvas'){
    const canvas=event.target, rect=canvas.getBoundingClientRect(), ctx=canvas.getContext('2d');
    const x=(event.clientX-rect.left)*canvas.width/rect.width, y=(event.clientY-rect.top)*canvas.height/rect.height;
    const label=Object.entries(WATER_MAP_LABELS).find(([, [left,top]])=>Math.abs(left-x)<62&&Math.abs(top-y)<21);
    const district=label?.[0]||DAEGU_DISTRICTS.find(name=>ctx.isPointInPath(waterMapPath(name),x,y,'evenodd'));
    if(district)selectWaterMapDistrict(district);
    return;
  }
  const mapLink=event.target.closest('[data-map-provider]');
  if(mapLink&&$('#remember-map-provider')?.checked){
    store.prefs.mapProvider=mapLink.dataset.mapProvider;
    persist();render(false);
  }
  const advancedSummary=event.target.closest('#shelter-advanced > summary');
  if(advancedSummary)shelterAdvancedOpen=!advancedSummary.parentElement.open;
  const selected=event.target.closest('button[data-action]');if(!selected)return;
  const action=selected.dataset.action;
  if (Object.hasOwn(navItems,action)) navigate(action);
  else if(action==='water-publish'||action==='water-report'||action==='cpr-age')handlers[action](selected.dataset.value,selected);
  else handlers[action]?.(selected.dataset.value);
});
document.addEventListener('input',event=>{if(!['radio','checkbox','select-one'].includes(event.target.type))fieldChange(event.target,false);});
document.addEventListener('change',async event=>{
  if(event.target.id!=='backup-file'){fieldChange(event.target,true);return;}
  const file=event.target.files?.[0];if(!file)return;
  try{
    if(file.size>10*1024*1024)throw Error('10MB 이하의 기록 백업을 선택하세요.');
    const count=importRecords(await file.text());persist();render(false);
    showDialog('훈련 기록 가져오기',`<div class="stack"><p>${count?`${count}건을 가져왔습니다.${storageOK?'':' 이번 세션에서 사용할 수 있습니다.'}`:'새로 가져올 기록이 없습니다.'}</p>${button('확인','dismiss',{kind:'primary'})}</div>`);
  }catch(error){showDialog('기록을 가져오지 못했습니다',`<div class="stack"><p>${escapeHTML(error.message)}</p>${button('확인','dismiss')}</div>`);}
  finally{event.target.value='';}
});
window.addEventListener('afterprint',()=>document.body.classList.remove('printing-report'));
window.addEventListener('storage',event=>{
  if(event.key===metaKey&&event.newValue){
    try{
      const prev=JSON.parse(event.oldValue||'{}'), next=JSON.parse(event.newValue);
      if(JSON.stringify(prev.draft)!==JSON.stringify(next.draft))store.draft=next.draft||null;
      if(JSON.stringify(prev.heldDrafts)!==JSON.stringify(next.heldDrafts))store.heldDrafts=next.heldDrafts||[];
      store.prefs={...defaultPrefs,...next.prefs};savedMeta=event.newValue;
      if(!store.draft&&['facility','plan','setup','coach'].includes(view))navigate('records');
      else if(view==='records'||view==='home')render(false);
    }catch{return;}
    return;
  }
  if(!event.key?.startsWith(runKey))return;
  const id=event.key.slice(runKey.length), local=recordBy(id);
  if(!event.newValue){
    store.runs=store.runs.filter(r=>r.id!==id);savedRuns.delete(id);
    if(id===runId&&['training','results','results-detail','whatif','fork-training','fork-result','improve','compare','review'].includes(view)){
      runId=null;branchId=null;dismiss();navigate('records');
    }else if(view==='records'||view==='home')render(false);
    return;
  }
  if(local&&(JSON.stringify(local)!==savedRuns.get(id)||(id===runId&&['training','fork-training','improve'].includes(view)))){
    storageConflict='같은 기록이 다른 탭에서 바뀌었습니다. 필요하면 이 탭의 변경 내용을 백업하세요.';
    setLive(storageConflict);return;
  }
  try{const remote=loadRecord(event.newValue);if(!remote)return;if(local)store.runs[store.runs.indexOf(local)]=remote;else store.runs.push(remote);savedRuns.set(id,JSON.stringify(remote));}catch{return;}
  if(view==='records'||view==='home')render(false);
});
document.addEventListener('submit',event=>{
  if(event.target.id==='finder-search-form'){
    event.preventDefault();
    if(!isFinderPage(view))return;
    const query=String(new FormData(event.target).get('finder-query')||'').trim().slice(0,100);
    if(!query)return;
    finderLocation.query=finderLocation.searched=query;
    finderLocation.matches=finderSearch(query);
    render(false);
    focusSection($('#finder-match-status'),'nearest');
    return;
  }
  if(event.target.id==='live-advice-form'){
    event.preventDefault();
    liveAdviceText=String(new FormData(event.target).get('live-text')||'').trim().slice(0,240);
    if(!liveAdviceText)return;
    const {situation,support}=readLiveSupport(liveAdviceText);
    if(!liveSubjectManual)liveSubject=inferLiveSubject(situation)||(support?.kind==='selfAlone'?'self':inferLiveSubject(liveAdviceText))||liveSubject;
    const choice=choiceFromLiveSupport(support,liveSubject);
    if(choice)liveSupportSelection[liveSubject]={choice,fromText:true};
    else if(liveSupportSelection[liveSubject]?.fromText)liveSupportSelection[liveSubject]=null;
    if(!liveAdviceManualPlace){
      const locations=Object.keys(DRILL_PLACES).filter(id=>DRILL_PLACES[id].words.test(liveAdviceText));
      liveAdvicePlace=locations.length===1?locations[0]:'';
    }
    const key=matchLiveSituation(situation);
    setLiveAdvice(key,key==='unknown'?'unclear':'text');return;
  }
  if(event.target.id==='water-recover-form'){
    event.preventDefault();restoreWaterOwner(event.target);return;
  }
  if(event.target.id==='water-flag-form'){
    event.preventDefault();sendWaterFlag(event.target);return;
  }
  if(event.target.id==='drill-responders-form'){
    event.preventDefault();
    const form=event.target,fields=new FormData(form),id=fields.get('scenario');
    const responders=readResponderCount(form);
    if(responders===null||!Object.hasOwn(SCENARIOS,id))return;
    dismiss();
    startGuidedRun(newDraft(true,id),id,responders,null,fields.get('drill-run-difficulty')||store.prefs.drillDifficulty);
    return;
  }
  if(event.target.id==='community-heat-manual'){event.preventDefault();submitCommunityWeather(event.target);return;}
  if(event.target.id==='site-drill-form'){

    event.preventDefault();startSiteDrill(event.target);return;
  }
  if(event.target.id==='field-plan-form'){
    event.preventDefault();
    fieldSite=readFieldSite(event.target);
    fieldPlan=String(new FormData(event.target).get('field-plan')||'').slice(0,FIELD_PLAN_MAX);
    runFieldPlanCheck();return;
  }
  if(event.target.id==='water-form'){
    event.preventDefault();
    if(waterBusy)return;
    const values=Object.fromEntries([...new FormData(event.target)].map(([key,value])=>[key.slice(6),value]));
    const {item,errors}=validateWaterEvent(values);waterErrors=errors;
    if(Object.keys(errors).length){waterDraft={...WATER_EMPTY,...values};waterPlanner.open=!!errors.bottles||$('#water-planning').open;render(false);const invalid=$(`#water-${Object.keys(errors)[0]}`);invalid?.focus();return;}
    const id=waterEditId||newId();
    const existing=waterItems.find(row=>row.id===id&&row.owned);
    if(existing?.live){
      const form=event.target;
      waterMutation(existing,{data:{event:item},statusField:$('#water-form-status'),control:form.querySelector('[type="submit"]'),after:()=>{
        if(!form.isConnected)return;
        waterMode='mine';waterDistrict='all';navigate('water-events');waterManager(id);$('#water-manager-status').textContent='공개 일정을 변경했습니다.';
      }});
      return;
    }
    waterItems=waterItems.filter(row=>row.id!==id);waterItems.push({...existing,...item,id,owned:true});saveWaterItems();
    waterMode='mine';waterDistrict='all';navigate('water-events');waterManager(id);return;
  }
  if(event.target.id!=='facility-form')return;
  event.preventDefault();if(validDraft('facility'))draftTo('plan');
});
// Keep mobile form controls clear of the on-screen keyboard and navigation.
const appViewport=window.visualViewport, keyboardLayout=matchMedia('(max-width: 999px)');
if(appViewport){
  function syncKeyboard(){
    const focused=document.activeElement;
    const input=focused?.matches('textarea,input:not([type=radio]):not([type=checkbox]):not([type=range]),select');
    const keyboard=keyboardLayout.matches&&input&&appViewport.scale<1.05&&window.innerHeight-appViewport.height>120;
    document.body.toggleAttribute('data-keyboard-open',keyboard);
    if(keyboard&&focused.getBoundingClientRect().bottom>appViewport.offsetTop+appViewport.height-24){
      focused.scrollIntoView({block:'center',behavior:'instant'});
    }
  }
  appViewport.addEventListener('resize',syncKeyboard);
  document.addEventListener('focusin',syncKeyboard);
  document.addEventListener('focusout',()=>requestAnimationFrame(syncKeyboard));
}
const linkedScenario=new URLSearchParams(location.search).get('scenario');
if(Object.hasOwn(SCENARIOS,linkedScenario))view='linked-drill';
function openWaterHash(){
  if(location.hash.startsWith('#water-live=')){
    const id=location.hash.slice(12);
    waterLiveId=WATER_ID.test(id)?id:'';sharedWater=null;sharedWaterError=!waterLiveId;waterSharedConnection='loading';return true;
  }
  const parsed=readSharedWater(location.hash);
  if(parsed===null)return false;
  waterLiveId='';sharedWater=parsed||null;sharedWaterError=parsed===false;return true;
}
function openPublicHash(){
  if(location.hash==='#aed')return 'aed-finder';
  if(location.hash.startsWith('#field=')){
    const clean=new URL(location.href);
    clean.hash='';
    history.replaceState(history.state,'',clean);
    return 'field-manager';
  }
  return openWaterHash()?'water-shared':null;
}
view=openPublicHash()||view;
window.addEventListener('hashchange',()=>{
  const page=openPublicHash();
  if(page==='aed-finder')openAedFinder();
  else if(page)navigate(page);
});
